quests[79094] = { id = 79094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lehren von Ta'zo", progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, {name}. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte." }
quests[79095] = { id = 79095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Metaphysische Fibel des Apothekers", progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, {name}. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte." }
quests[79096] = { id = 79096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ataeric: Arkane Merkwürdigkeiten", progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, {name}. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte." }
quests[79097] = { id = 79097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baxtan: Über zerstörerische Magie", progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, {name}. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte." }
quests[79098] = { id = 79098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haltet den Wald frei!", description = "Der hier wurde besiegt, doch diese ärgerliche Allianz kämpft nach wie vor weiter... Was ist das für ein Amulett?", sourceObjective = "Bringt das Amulett der Schildwache der Silverwing zu Scharfseher Kazragore in der Freudenfeuerbasis in Ashenvale.", progress = "{name}, welche Neuigkeiten bringt Ihr von der Front?", completion = "Diese Hunde von der Allianz halten uns weiterhin davon ab, die Ressourcen für Orgrimmar zu sammeln. Treibt sie weiterhin hinaus!\n\nDiese Warsongkampftrommel wird Euch inspirieren, mit noch größerer Entschlossenheit gegen sie anzukämpfen. Lok'tar ogar, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[79099] = { id = 79099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baron Aquanis", description = "Seid gegrüßt, {class}. Ich habe von den Ortsansässigen überaus kuriose Geschichten über einen großen, verderbten Wasserelementar namens Baron Aquanis gehört, der in der Nähe des Eingangs der als Blackfathom-Tiefe bekannten Nachtelfenruine Wache steht. Ich bin hier, um Abenteurer anzuheuern, die genug Mumm haben, den Kern von Baron Aquanis zu bergen, eine Kugel verderbten Wassers. Im Austausch wäre ich bereit, Euch Zugang zu einem Portal direkt an den Zoramstrand zu gewähren, das ich zur Erkundung der Landschaft um die Ruinen herum nutze... aus sicherer Distanz, natürlich.", sourceObjective = "Bringt die seltsame Wasserkugel zu Davius Leerenstern in Auberdine an der Dunkelküste.", progress = "Ah, hallo, {name}. Konntet Ihr die Kugel bergen?", completion = "Hmm, überaus kurios. Das... ist nicht, was ich erwartet hatte. Nun, dennoch vielen Dank. Versprochen ist versprochen. Ihr dürft ab sofort mein Portal an den Zoramstrand verwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[79100] = { id = 79100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine abgefangene Lieferung", sourceObjective = "In dieser Lieferung fehlen einige Gegenstände, aber sie wird sich dennoch als nützlich erweisen. Vielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[79101] = { id = 79101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine komplette Lieferung", progress = "Habt Ihr etwas für mich?", completion = "Es ist alles da! Vielen Dank, {name}. Diese Vorräte sind an vorderster Front unentbehrlich." }
quests[79102] = { id = 79102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine komplette Lieferung", progress = "Habt Ihr etwas für mich?", completion = "Es ist alles da! Vielen Dank, {name}. Diese Vorräte sind an vorderster Front unentbehrlich." }
quests[79103] = { id = 79103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine komplette Lieferung", progress = "Habt Ihr etwas für mich?", completion = "Es ist alles da! Vielen Dank, {name}. Diese Vorräte sind an vorderster Front unentbehrlich." }
quests[79192] = { id = 79192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trittsteine", description = "Die Notiz beginnt folgendermaßen: \"Die Mission besagt, dass sie beide Lieferungen für die neue Seuche erledigt hätten. Auf mich haben sie jedoch eher wie einfache Apothekerunfälle gewirkt. Findet meinen gemütlichen Platz in den Bergen zwischen dem Brachland und Desolace, wenn Ihr einen sicheren Ort zum Reden sucht.\"", sourceObjective = "Ihr reißt die Notiz von der Planke und lest die verschmierte Schrift.", completion = "Zweifellos schlagen Abenteurer und Söldner aus dem Hinterland hier ihr Lager auf. Die Ecke einer im Wind flatternden Notiz fällt Euch ins Auge und Ihr greift danach.", sourceObjectiveStatus = "unverified-source-field" }
quests[79229] = { id = 79229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Straßenraub", description = "Der Lagerplatz vor Euch sieht grausig aus. Den Überresten nach zu schließen, waren die Opfer zwei Menschen und ein Zwerg. Spuren auf den Knochen deuten auf einen schweren Angriff hin, aber die gestohlenen Vorräte sagen Euch, dass es keine wilden Tiere waren. Die Wunden passen auch nicht zu den Waffen der Zentauren.\n\nVielleicht weiß ein erfahrener Plünderer dieses Landes mehr.", sourceObjective = "Findet jemanden in Desolace, der etwas über das geplünderte Lager weiß.", completion = "Ah, Ihr habt also noch eine gefunden...", sourceObjectiveStatus = "unverified-source-field" }
quests[79235] = { id = 79235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Flucht", description = "Ich habe einige Szenen, wie Ihr sie beschreibt, gefunden, {name}. Es sind immer Lager von Menschen und Zwergen. Es gibt Gerüchte unter den Karawanen, dass es eine Gruppe von Plünderern der Horde war. Den Opfern und der Brutalität der Angriffe nach zu urteilen, scheint das wahrscheinlich.\n\nAnscheinend sind die Banditen nach Desolace geflohen, nachdem ein Marschall der Allianz ihnen auf die Spur gekommen ist.\n\nIch würde es mit einer Hafenstadt versuchen, wenn Ihr einen von ihnen aufspüren wollt. Da wimmelt es immer von zwielichtigen Gestalten. Vielleicht erwischt Ihr einen beim Versuch, ein Boot nach irgendwo zu bekommen.", sourceObjective = "Findet einen der Plünderer von Desolace.", completion = "Braucht ihr etwas? Macht es kurz.", sourceObjectiveStatus = "unverified-source-field" }
quests[79236] = { id = 79236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Kirsche für Eure Gedanken", description = "Gehört Ihr zu dem Marschall? Nein, so seht Ihr nicht aus.\n\nDie Gerüchte, die Ihr gehört habt, sind nur zur Hälfte wahr. Ja, wir haben Lager der Menschen und Zwerge geplündert, aber wir haben es nicht für die Horde getan. Wir wurden privat angeheuert.\n\nIch erzähle Euch die ganze Geschichte, wenn Ihr mir einen Grog ausgebt.", sourceObjective = "Bringt einen Kirschgrog zu Tokal in Booty Bay, um den Rest ihrer Geschichte zu hören.", progress = "Wo bleibt mein Grog?", completion = "Ah, genau das brauche ich jetzt. Also, wo war ich?", sourceObjectiveStatus = "unverified-source-field" }
quests[79242] = { id = 79242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Ehre unter Dieben", description = "Wie gesagt...\n\nUnser Boss war nicht von der Horde. Sie war eine Nachtelfe namens Illari Dämmerfeder. Sie hat uns Informationen zu den Lagern gegeben und uns das meiste der Beute behalten lassen. Sie hat nur einige der wertvolleren Funde behalten.\n\nAls der Marschall uns auf die Spur gekommen ist, hat sie uns zurückgelassen. Ich kenne ihre Motive nicht, aber ich glaube, wir sollten als Sündenbock herhalten.\n\nIch bin nicht nachtragend, aber ich würde niemanden aufhalten, der sie finden will. Wenn Ihr sie sucht, sie hat einmal von einem Versteck irgendwo in der Nähe des Arathihochlands gesprochen.", sourceObjective = "Findet Illari Dämmerfeder in der Nähe des Arathihochlands und erhaltet Zugriff auf ihre Sammlung gestohlener Beute.", progress = "<Benutzt Illaris Schlüssel, um die Truhe aufzuschließen.>", completion = "<Im Inneren der Truhe findet Ihr eine kleine Schatulle und einige Münzen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[79298] = { id = 79298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal herausfordern", description = "Ihr könnt die üble Magie sehen, die das Wasser vergiftet und ihm einen violetten Schimmer verleiht. Die Brennende Klinge hat dieses Gebiet mit dunkler Magie überwältigt.\n\nWir werden diesen Opferaltar verwenden, den sie für ihre Beschwörungsrituale nutzen. Wir können die dunkle Energie in der Gegend nutzbar machen, um unser Ritual zu verstärken.", sourceObjective = "Unterstützt Raszel Ander und Doan Karhan beim Beschwörungsritual und schließt Des'Altek im Stab ein.", completion = "Von all den Dingen, die Raszel Ander war, hätte ich ihn am wenigsten als herrisch bezeichnet. Für einen {class} war er immer eher auf der sanftmütigen Seite. Ich dachte mir bereits, dass etwas nicht stimmt, als dieser Betrüger während Eures Beschwörungsrituals zurückkam. Das war auch der Grund, weshalb ich weitere Akolythen zur Unterstützung herbeigerufen habe, doch es waren nicht genug... Erneut haben wir versagt, unsere Beute zu fangen.\n\nLeider ist der Stab während Eures Kampfes zerbrochen und alles, was ich tun konnte, war hilflos dazustehen und zuzuschauen... Doch in den Trümmern habe ich das hier gefunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[79348] = { id = 79348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das verlorene Urtum", description = "Ein fauliger Samen ist alles, was von dem wandernden Urtum übrig ist. Seine äußere Hülle ist brüchig und das Innere gibt einen fauligen Geruch von sich.\n\nGemessen an seiner Größe, muss das Urtum, von dem dieser Samen stammt, recht jung gewesen sein. Zumindest für ein Urtum. Da stellt sich einem die Frage, weshalb ein solches Geschöpf durch den Morast wandelt.\n\nUm Antworten zu bekommen, solltet Ihr Euch an jemanden wenden, der sich mit der Geschichte der Urtume auskennt.", sourceObjective = "Findet jemanden, der Euch etwas zum verdorbenen Samen erzählen kann.", completion = "Ah, ein weiteres junges Leben verloren...", sourceObjectiveStatus = "unverified-source-field" }
quests[79358] = { id = 79358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerfledderte Notiz", description = "<Ihr entfaltet ein zerfleddertes Pergament, auf dem steht:>\n\nDie Tunnel haben die Klippen oberhalb von Tausend Nadeln erreicht und unsere Vorbereitungen blieben unbemerkt. Doch wir müssen rasch handeln. Entsendet Eure Schamanen. Nach allem, was Hirzek erreicht hat, sind wir bereit, zu beginnen.\n\nDer Sturm wird toben, der Boden wird erbeben und die Flut werde ansteigen, auf dass nur Leichen zurückbleiben, die wir auf unserem Pfad wiederbeleben können. Ihre Knochen werden einen Pfad in...\n\n<Die Nachricht endet mitten im Satz, weil der Rest der Seite fehlt.>", sourceObjective = "Warnt die Einwohner von Tausend Nadeln davor, was Ihr in Erfahrung gebracht habt.", completion = "<Hrmpf... Der große Tauren schnaubt, während er das Pergament liest.>\n\nEins ist sicher... Wer immer diese Notiz geschrieben hat, hatte recht: Wir haben nichts von ihren Vorbereitungen mitbekommen. Wir haben mit den Zentauren und Harpyien schon genug zu tun, als dass wir Windreiter entsenden könnten, um jede Schlucht und Klippe im Auge zu behalten.\n\nDanke, dass Ihr uns über die Bedrohung unterrichtet habt, aber vielleicht brauchen wir weiter Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[79360] = { id = 79360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementare Hilfe", description = "Ich hörte von Hirzek und den barbarischen Mühen, die sie aufgebracht haben, um die Elemente zu manipulieren.\n\n<Raus Blick wandert, während er über die Notiz nachdenkt und laut mit sich selbst spricht.>\n\nDer Sturm wird toben, der Boden wird erbeben und die Flut wird ansteigen...\n\n<Rau blickt Euch an und seine Augen weiten sich, als es ihm klar wird.>\n\nSie wollen irgendeine finstere Zauberei einsetzen, die sie von Hirzek gelernt haben. Sie haben vor, die Schlucht zu fluten, um uns alle als Untote wiederzuerwecken.\n\nIch fürchte, um das Ziel zu erreichen, brauchen sie verheerende elementare Kräfte.", sourceObjective = "Viele Bewohner von Tausend Nadeln mögen unsere Feinde sein, aber wir können nicht tatenlos zusehen, wie sie fortgespült werden. Die Nachricht war eindeutig: Sie planen, aus den Nachwehen eine untote Armee zu erwecken, die eine Bedrohung für uns alle werden könnte.\n\nWir sind kaum imstande, ihren Plänen etwas entgegenzusetzen, aber ich hörte von einem Schamanen in den Östlichen Königreichen, der in der elementaren Verzauberung von Waffen geübt ist. Er könnte vielleicht helfen.\n\nSucht diesen Schamanen auf und bittet ihn um seine Hilfe.", completion = "<Ihr überreicht Bath'rah die Notiz. Er überfliegt sie und schmunzelt halbherzig.>\n\nAh, es stimmt also, Mann... Ich hab die Unruhe in den Elementarebenen schon gespürt, und das is' wohl 'ne Ursache davon.\n\nUm ganz Tausend Nadeln zu flut'n, bräuchte man 'nen gewaltigen Sturm, viele würden sterb'n.\n\nIch glaub, ich hab genau das, was Ihr braucht, aber es wird nich' leicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[79361] = { id = 79361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht des Windes", description = "'N gewaltiger Sturm von dieser Größe braucht die Macht vom Wind, um das ganze Land heimzusuch'n. Was immer dieses Ritual is', wir müss'n Euch vor dem Element schütz'n.\n\nDie Wirbelwindelementare hab'n Desolace zerstört und gehören zu den wenig'n Elementaren, die das Land noch bewohn'n könn'. Bringt mir ihre Essenz.", sourceObjective = "Sammelt 5 wirbelnde Essenzen von den Wirbelwindelementaren in Desolace und bringt sie Bath'rah dem Windbehüter im Alteracgebirge.", progress = "Ah, seid Ihr da drauß'n 'n bisschen angestaubt?", completion = "Oh, ja, ja! Damit sind wir im Geschäft.", sourceObjectiveStatus = "unverified-source-field" }
quests[79362] = { id = 79362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht der Erde", description = "Um den Boden zum Beben zu bring'n, braucht man 'ne starke Verbindung zur Erde. Das Ödland ist voller Steine und Felsbrocken, die von der Zeit gehärtet wurd'n. Die Verkörperung der Erde treibt sich in diesen Ländern rum und nennt sie ihr Zuhause.", sourceObjective = "Sammelt 5 bebende Essenzen von den Felselementaren im Ödland und bringt sie Bath'rah dem Windbehüter im Alteracgebirge.", progress = "Ihr seht 'was wacklig auf den Beinen aus. Hat der Boden ordentlich gezittert?", completion = "'N steiniger Weg kann Euch nich' aufhalt'n, was?", sourceObjectiveStatus = "unverified-source-field" }
quests[79363] = { id = 79363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht des Wassers", description = "Diese Flut, die ist echt das Schlimmste, Mann. Die Schlucht ist staubtrocken und das Wasser fließt tagelang auf diesem harten brüchigen Bod'n, da ist das Becken im Nu weg.\n\nIch kenne nich' viele Elementare, die solche Macht in sich trag'n, aber...\n\n<Bath'rah schaut Euch mit einem gerissenen Lächeln an.>\n\nKeine Sorge, ich weiß, wie ich Euch helf'n kann.\n\nDer Morast der Marschen von Dustwallow, da solltet Ihr hin. Auch wenn die nich' reine Wasserelementare sind, diese Verdorrten haben Geheimnisse.", sourceObjective = "Sammelt 5 rauschende Essenzen von den verdorrten Elementaren in den Marschen von Dustwallow und bringt sie Bath'rah dem Windbehüter im Alteracgebirge.", progress = "Habt Ihr Euch 'was nass gemacht?", completion = "Schüttelt den Schlamm ab, Mann, wir hab'n's fast geschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[79364] = { id = 79364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein einfacher Behälter", description = "Gut gemacht, Mann. Ich weiß zwar nich', was Euch in Tausend Nadeln erwartet, aber das bietet Euch auf jeden Fall Schutz gegen die Elemente, die das Land bedroh'n.\n\n<Bath'rah sucht in seinen Sachen nach etwas und wirkt immer frustrierter, während er verzweifelt alles durchstöbert. Schließlich blickt er Euch kleinlaut an.>\n\nDa ist doch noch 'ne Sache, die ich von Euch brauch.\n\n<Er lächelt breit, bevor er weiterspricht.>\n\nIch hab offenbar meine Trankphiolen verlegt...", sourceObjective = "Ihr habt doch nich' gedacht, dass ich irgend'ne verrückte Waffe für Euch entwickle, hm? Nee, nee, nee, <mein Freund/meine Liebe>, das ist 'n Schutztrank.\n\nFeuer mit Feuer zu bekämpfen, ist nicht immer der richtige Weg, Mann.\n\nBringt eine Kristallphiole zu Bath'rah dem Windbehüter im Alteracgebirge.", progress = "Wir brauch'n 'ne größere Phiole, und zwar eine von kristallener Klarheit, um diese Elemente zu bewahr'n.", completion = "Ich wusste, ich kann auf Euch zähl'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[79365] = { id = 79365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Wind unter Euren Schwingen", description = "Hier, Mann, 'n Böenbrechertrank ist genau, was Ihr braucht. Trinkt ihn, um Euch vor den Elementen des Sturms zu schütz'n, aber denkt dran: Die Wirkung hält nur kurz an.\n\nAlso los, kehrt zu Euren Freund'n in Not zurück. Ich kann nichts weiter für Euch tun.", sourceObjective = "Kehrt zu Rau Cliffrunner im Freiwindposten in Tausend Nadeln zurück.\n\nBereitgestellter Gegenstand:", completion = "Unsere Windreiter haben etwas entdeckt, aber sie kamen nicht nah genug heran, um die Situation zu beurteilen. Habt Ihr etwas entdeckt, was uns womöglich hilft?", sourceObjectiveStatus = "unverified-source-field" }
quests[79366] = { id = 79366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruhe vor dem Sturm", description = "Wir haben ungewöhnlich starke Sturmaktivitäten entdeckt, die auf die Klippen im Nordosten nahe des Territoriums der Razorfen beschränkt sind.\n\nDie Winde waren so heftig, dass die Reiter nicht näher herankamen, und im dichten Regen konnten sie unmöglich sehen, was im Auge des Sturms vor sich geht. Aber vielleicht gelangt Ihr mit diesem Trank auf die andere Seite.\n\nSprecht mit Nyse, der Windreitermeisterin, wenn Ihr bereit seid. Sie stellt Euch einen Flügeldrachen bereit, um in den Sturm zu reiten.", sourceObjective = "Wagt Euch ins Auge des Sturms und stellt die Stacheleber.", progress = "Was habt Ihr gefunden?", completion = "Das Grollen der Erde verstummte und in meinem Herzen wusste ich, dass Ihr uns gerettet habt. Ich schulde Euch Dank, {name}.\n\nBitte akzeptiert eines dieser Geschenke als Ausdruck unserer Verbundenheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[79377] = { id = 79377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorenen Schösslinge", description = "In unruhigen Zeiten können die Samen von Urtumen ihre Wurzeln in bitterer Erde schlagen. Urtume, die auf diese Weise geboren werden, sind anfällig, der Verderbnis zu verfallen. Sie durchschreiten feindselige Lande und finden nie Frieden.\n\nIch habe vier Schösslinge aufgespürt, denen ein solches Schicksal möglicherweise erspart bleiben kann. Sie sind in den Östlichen Königreichen verloren gegangen und tragen Blätter wie die der vier Jahreszeiten.\n\nBitte, bringt ihnen dieses Wasser, auf dass sie geheilt werden mögen.\n\nVorsicht, die Magie des Wassers ist empfindlich. Teleportation zerstört sie. Seine Wirksamkeit wird darüber hinaus mit der Zeit abnehmen.", sourceObjective = "Findet die vier verlorenen Schösslinge in den Östlichen Königreichen und gebt ihnen das Wasser aus Elune'ara. Kehrt anschließend mit ihnen wieder zu Orokai in Moonglade zurück.", completion = "Eure Taten haben Jahrhunderte des Lebens erhalten, {name}. Ich bin Euch unermesslich dankbar. Möget Ihr noch mehr Heilung ins Land tragen in den Zeiten, die uns bevorstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79442] = { id = 79442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufholen", description = "Unsere Leute können Euch nicht genug danken, doch ich habe keinen wirklichen Nutzen für dieses Auge. Vielleicht kann der alte Windbehüter etwas damit anfangen.", sourceObjective = "Kehrt zu Bath'rah dem Windbehüter im Alteracgebirge zurück und seht, ob er etwas mit dem Auge des Gewittersturms anfangen kann.", progress = "Ahh! Ihr habt's also unversehrt zurückgeschafft! Also, erzählt, wie hat sich der Trank gemacht?\n\nZum Glück hab ich an Euch geglaubt. Weil der Trank ist nur ein feiner Punsch, Kollege. Lecker, aber nich' sehr effektiv geg'n solche Stürme.\n\nNa, na... nicht böse werd'n. Ihr habt nur 'n bisschen Ermutigung gebraucht. Lief doch alles wie geplant.\n\nAber wo Ihr schon mal hier seid... Mir ist das schöne Auge aufgefall'n, das Ihr da habt.", completion = "Ich sag Euch was. Keine Tricks mehr, keine Spielchen. Ich hab da was, was Euch interessier'n könnte.\n\nGebt mir das Auge und ich geb Euch diese schicke Rune, die Euch neue Tricks beibring'n kann.\n\nWas meint Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[79482] = { id = 79482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlene Winterhauch-Leckereien", description = "Hört zu... ich will Euch ja den Zauber der Feiertage nicht verderben, aber Kokelwälder könnte etwas Hilfe brauchen... von der Art, für die Ihr Abenteurer bekannt seid.\n\nUns ist eine wichtige Lieferung mit Leckereien abhandengekommen, mit der wir die Vorräte für diese Feiertage aufstocken wollten, und jetzt ist auch noch der Agent von Kokelwälder verschwunden, den wir losgeschickt haben, um sie zu suchen! Also, die letzten Informationen über die Lieferung stammen aus dem Alteracgebirge, und dort wollte unser Mann danach suchen.\n\nSeht nach, ob sowohl Mann als auch Material dort zu finden sind, und zwar gesund und munter.", sourceObjective = "Sucht den Ermittler von Kokelwälder, der im Alteracgebirge vermisst wird.", completion = "I-I-Ihr könnt mich h-h-hören! G-G-Gott sei Dank!\n\nIch bin nicht wirklich ein Sch-Sch-Schneemann - mein N-N-Name ist Sacks und ich a-a-arbeite für die N-N-Niederlassung von Kokelwälder in Ironforge. Ich w-w-wurde hierher geschickt, um n-n-nach einem vermissten Paket zu suchen, als ich von einer K-K-Kreatur angegriffen wurde, die ich n-n-noch nie gesehen habe!\n\nSo k-k-kalt...", sourceObjectiveStatus = "unverified-source-field" }
quests[79483] = { id = 79483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlene Winterhauchleckereien", description = "Hört zu... ich will Euch ja den Zauber der Feiertage nicht verderben, aber Kokelwälder könnte etwas Hilfe brauchen... von der Art, für die Ihr Abenteurer bekannt seid.\n\nUns ist eine wichtige Lieferung mit Leckereien abhanden gekommen, mit der wir die Vorräte für diese Feiertage aufstocken wollten, und jetzt ist auch noch der Agent von Kokelwälder verschwunden, den wir losgeschickt haben, um sie zu suchen! Also - die letzten Informationen über die Lieferung stammen aus dem Alteracgebirge, und dort wollte unser Mann danach suchen.\n\nSeht nach, ob sowohl Mann als auch Material dort zu finden sind, und zwar gesund und munter.", sourceObjective = "Sucht den Ermittler von Kokelwälder, der im Alteracgebirge vermisst wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[79484] = { id = 79484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So was Gemeines...", description = "Eine K-K-Kreatur namens \"Der monströse Griesgram\" hat u-u-unsere Lieferung mit L-L-Leckereien gestohlen, {name}. Seid a-a-aber vorsichtig! Er hat m-m-mich in dieses Sch-Sch-Schneeschlamassel verwandelt!\n\nIhr w-w-werdet Hilfe brauchen, wenn Ihr ihm g-g-gegenübertretet. Ich habe gesehen, w-w-wie er dort herumzieht, wo die Y-Y-Yetis sind. Er ist s-s-sicherlich irgendwo h-h-hier! F-F-Findet die Leckereien, {name}, bringt sie zu Kokelwälder in Ironforge z-z-zurück und s-s-sagt ihnen, dass ich a-a-aufgetaut werden muss!", sourceObjective = "Sucht die gestohlenen Leckereien und bringt sie zu Wulmort Jinglepocket nach Ironforge. Zuletzt befanden sie sich im Besitz des monströsen Griesgrams, der sich in den Schneegebieten des Alteracgebirges befindet.", progress = "{name}, unser Winterhauchfest ist ruiniert, wenn wir unsere Lager nicht mit diesen Leckereien auffüllen können! Graccu kommt bestimmt zu kurz, wenn er dieses Mal seine köstlichen Fleischpasteten mit all den braven Jungs und Mädchen teilen muss...", completion = "Ihr habt sie gefunden! Ihr habt das Winterhauchfest für Kokelwälder gerettet!\n\nArmer Sacks... Wir werden ein Team rausschicken und uns eine Möglichkeit überlegen, wie wir ihn wieder auftauen. Hoffentlich ist er rechtzeitig zum Festtag zurück. Allerdings muss er noch die ganze Arbeit aufholen, die inzwischen liegen geblieben ist. Aber ohne Euch wäre auch das nicht möglich!", sourceObjectiveStatus = "unverified-source-field" }
quests[79485] = { id = 79485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So was Gemeines...", description = "Eine K-K-Kreatur namens \"Der monströse Griesgram\" hat u-u-unsere Lieferung mit L-L-Leckereien gestohlen, {name}. Seid a-a-aber vorsichtig! Er hat m-m-mich in dieses Sch-Sch-Schneeschlamassel verwandelt!\n\nIhr w-w-werdet Hilfe brauchen, wenn Ihr ihm g-g-gegenübertretet. Ich habe gesehen, w-w-wie er dort herumzieht, wo die Y-Y-Yetis sind. Er ist s-s-sicherlich irgendwo h-h-hier! F-F-Findet die Leckereien, {name}, bringt sie zu K-k-k-kokelwälder in Orgrimmar z-z-zurück und s-s-sagt ihnen, dass ich a-a-aufgetaut werden muss!", sourceObjective = "Sucht die gestohlenen Leckereien und bringt sie zu Kaymard Copperpinch nach Orgrimmar. Zuletzt befanden sie sich im Besitz des monströsen Griesgrams, der sich in den Schneegebieten des Alteracgebirges befindet.", sourceObjectiveStatus = "unverified-source-field" }
quests[79486] = { id = 79486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Dankeschön von Kokelwälder!", description = "Wir von Kokelwälder sind dankbar für die Wiederbeschaffung der gestohlenen Leckereien, {name}. Dafür möchten wir Euch ein besonderes Geschenk anbieten... präsentiert von niemand Geringerem als Altvater Winter persönlich!\n\nBitte, sprecht mit Altvater Winter und er wird Euch Euer Geschenk zum Winterhauchfest von uns hier bei Kokelwälder überreichen. Frisch von unserem Hof auf Euren Tisch: beste Kokelwälder Vollwertkost... dank Euch natürlich!", sourceObjective = "Sprecht mit Altvater Winter in Ironforge.", completion = "Ho, ho, hallo!\n\nDie Goblins haben mir gesagt, dass Ihr in dieser Feiertagszeit ein besonderes Geschenk verdient habt, und ich freue mich, es Euch überreichen zu dürfen. Bitte schön - ich wünsche Euch für dieses Jahr und für alle kommenden Jahre ein wunderbares Winterhauchfest.", sourceObjectiveStatus = "unverified-source-field" }
quests[79487] = { id = 79487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Dankeschön von Kokelwälder!", description = "Wir von Kokelwälder sind dankbar für die Wiederbeschaffung der gestohlenen Leckereien, {name}. Dafür möchten wir Euch ein besonderes Geschenk anbieten... präsentiert von niemand Geringerem als Altvater Winter persönlich!\n\nBitte, sprecht mit Altvater Winter und er wird Euch Euer Geschenk zum Winterhauchfest von uns hier bei Kokelwälder überreichen. Frisch von unserem Hof auf Euren Tisch - beste Kokelwälder Vollwertkost... dank Euch natürlich!", sourceObjective = "Sprecht mit Altvater Winter in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[79492] = { id = 79492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Metzen das Rentier", description = "Es ist eine KATASTROPHE! Metzen das Rentier wurde entführt!\n\nMetzen ist eines von Altvater Winters acht Rentieren - und Eigentum von Kokelwälder. Wir haben nicht nur einen, sondern ZWEI Erpresserbriefe von Gruppen erhalten. Beide behaupten, Metzen in ihrer Gewalt zu haben. Gerade jetzt zur Festtagszeit haben wir hier ein echtes Problem. Bitte findet Metzen und bringt ihn zurück!\n\nSchaut Euch die Erpresserbriefe an, vielleicht findet Ihr darin ja Hinweise. Streut diesen Rentierstaub über ihn, wenn Ihr ihn findet, er wird ihn aus sämtlichen Fesseln befreien!\n\nBitte, beeilt Euch!", sourceObjective = "Findet Metzen das Rentier. Lest Euch die erhaltenen Notizen durch, um Tipps über seinen Aufenthaltsort zu erhalten.\n\nWenn Ihr Metzen findet, solltet Ihr den Beutel mit Rentierstaub dabeihaben. Berieselt Ihr Metzen mit dem Staub, sollte dies ihn aus seiner Gefangenschaft befreien.\n\nBringt den Beutel zu Wulmort Jinglepocket in Ironforge zurück, sobald Ihr Metzen befreit habt.", progress = "{name}! Habt Ihr ihn gefunden? Konntet Ihr den Notizen, die ich Euch mitgegeben habe, genug Informationen entnehmen, um ihn ausfindig zu machen? Mir wird ganz schlecht wenn ich daran denke, was diese fiesen Strolche ihm antun könnten... Ein so hohes Lösegeld können wir uns einfach nicht leisten.", completion = "Ihr habt es geschafft! Hurra!\n\nMetzen ist gerade eben erst zurück zu den Ställen von Altvater Winter geflogen. Ja, Metzen kann wirklich fliegen! Der Staub hat ganze Arbeit geleistet, ich wusste, das würde funktionieren. Ihr habt das Winterhauchfest und Kokelwälder vor dem Untergang bewahrt. Danke, {name}.\n\nHört mal, weil Ihr das für uns getan habt, möchte ich Euch das hier geben. Das ist etwas GANZ Besonderes. Wenn Ihr ein Reittier habt, werdet Ihr bestimmt eine Menge Spaß damit haben. Frohes Winterhauchfest!", sourceObjectiveStatus = "unverified-source-field" }
quests[79495] = { id = 79495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Metzen das Rentier", description = "Es ist eine KATASTROPHE! Metzen das Rentier wurde entführt!\n\nMetzen ist eines von Altvater Winters acht Rentieren - und Eigentum von Kokelwälder. Wir haben nicht nur einen, sondern ZWEI Erpresserbriefe von Gruppen erhalten. Beide behaupten, Metzen in ihrer Gewalt zu haben. Gerade jetzt zur Festtagszeit haben wir hier ein echtes Problem. Bitte findet Metzen und bringt ihn zurück!\n\nSchaut Euch die Erpresserbriefe an, vielleicht findet Ihr darin ja Hinweise. Streut diesen Rentierstaub über ihn, wenn Ihr ihn findet, er wird ihn aus sämtlichen Fesseln befreien!\n\nBitte, beeilt Euch!", sourceObjective = "Findet Metzen das Rentier. Lest Euch die erhaltenen Notizen durch, um Tipps über seinen Aufenthaltsort zu erhalten.\n\nWenn Ihr Metzen findet, solltet Ihr den Beutel mit Rentierstaub dabeihaben. Berieselt Ihr Metzen mit dem Staub, sollte dies ihn aus seiner Gefangenschaft befreien.\n\nBringt den Beutel zu Kaymard Copperpinch in Orgrimmar zurück, sobald Ihr Metzen befreit habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[79501] = { id = 79501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Held des Tages", description = "Eigentlich darf ich Euch das gar nicht sagen, aber da Ihr ja <der Held/die Heldin> des Tages seid, mach ich mal 'ne Ausnahme.\n\nUm diese Jahreszeit gibt es überall frische Tannenzweige, aber die Zweige bleiben nicht lange frisch. Wir haben eine Maschine, die Tannenzweige konserviert. Die bleiben dann für immer frisch! Wir benutzen sie, um die Festtage etwas aufzupeppen... und unsere Profite im Sommer zu steigern!\n\nIch lasse Euch den Konservierer benutzen, aber nur, wenn Ihr <ein Meisterkoch/eine Meisterköchin> seid. Ihr werdet etwas Tiefsteinsalz und etwa zwei, drei, ach, sagen wir einfach fünf Goldstücke brauchen. Damit solltet Ihr ein nettes Bündel konservieren können, das Ihr behalten könnt.", sourceObjective = "Bringt 1 Tiefsteinsalz und 5 Goldstücke zum Tannenzweigkonservierer. Ihr werdet 5 konservierte Tannenzweige erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[79502] = { id = 79502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Held des Tages", description = "Eigentlich darf ich Euch das gar nicht sagen, aber da Ihr ja <der Held/die Heldin> des Tages seid, mach ich mal 'ne Ausnahme.\n\nUm diese Jahreszeit gibt es überall frische Tannenzweige, aber die Zweige bleiben nicht lange frisch. Wir haben eine Maschine, die Tannenzweige konserviert. Die bleiben dann für immer frisch! Wir benutzen sie, um die Festtage etwas aufzupeppen... und unsere Profite im Sommer zu steigern!\n\nIch lasse Euch den Konservierer benutzen, aber nur, wenn Ihr <ein Meisterkoch/eine Meisterköchin> seid. Ihr werdet etwas Tiefsteinsalz und etwa zwei, drei, ach, sagen wir einfach fünf Goldstücke brauchen. Damit solltet Ihr ein nettes Bündel konservieren können, das Ihr behalten könnt.", sourceObjective = "Bringt 1 Tiefsteinsalz und 5 Goldstücke zum Tannenzweigkonservierer. Ihr werdet 5 konservierte Tannenzweige erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[79535] = { id = 79535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basilisken: Muss man Angst vor der Versteinerung haben?", progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, {name}. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte." }
quests[79536] = { id = 79536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großer Freund der Bibliothek", sourceObjective = "Dank Eurer Spenden entwickelt sich die Bibliothek prächtig.\n\nBitte, nehmt das.", sourceObjectiveStatus = "unverified-source-field" }
quests[79588] = { id = 79588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleine pelzige Tatzen", progress = "Will man eine große Masse herbeilocken, sollte man vor allem eines wissen: wie man mit kleinen Anreizen und Krimskrams ihr Interesse weckt! Könnt Ihr mir dabei helfen?\n\nIch brauche kleine pelzige Tatzen, die ich als Preise verwenden kann. Ihr könnt dergleichen von den Katzen des Brachlands oder der Dunkelküste erhalten...\n\nBringt mir ein paar Tatzen und ich tausche sie gegen ein Los des Dunkelmond-Jahrmarkts ein.", completion = "Großartig, Ihr habt sie! Wir können daraus Spielsachen und anderen Schnickschack herstellen und damit bei mehr und mehr Leuten Interesse für den Jahrmarkt wecken!\n\nHier ist Euer Los, {name}.  Ihr habt es Euch verdient!" }
quests[79589] = { id = 79589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerrissene Bärenpelze", progress = "Kinder lieben Spielsachen! Egal was für Kinder, ich habe herausgefunden, dass alle Kinder pelzige und kuschelige Spielsachen lieben, die aus zerrissenem Bärenpelz angefertigt wurden!\n\nIhr könnt diese Pelze von Bären aus Ashenvale oder Hillsbrad bekommen.  Bringt mir einen Haufen davon und verdient Euch damit eine Menge Lose des Dunkelmond-Jahrmarkts!", completion = "Schöne Pelze, {name}! Ich werde daraus eine Menge Kuscheltiere nähen lassen. Mit Hilfe von etwas Füllmaterial und Farbe, könnte daraus eines der begehrtesten Spielsachen in ganz Azeroth werden!\n\nLose? Ach ja, Euer Entgelt!  Hier sind sie!" }
quests[79590] = { id = 79590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwerer Schleifstein" }
quests[79591] = { id = 79591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surrendes bronzenes Dingsda", progress = "Mein neuer Stand wird etwas, das man sehen muss, ja! Etwas, das man sehen muss und... für ein paar Glückliche ist es auch etwas zum Anfassen!\n\nIch kann schon das mechanische Entzücken der surrenden kleinen Dingsdas hören und sehe schon die Kunden vor mir, wie sie näher an meinen Stand treten, um ihre Fähigkeiten zu testen!\n\nAh... jetzt brauche ich die Dingsdas selbst, um meinem Traum ein Stückchen näher zu kommen. Bitte, {name}, bringt mir surrende bronzene Dingsdas... und ein paar Lose des Dunkelmond-Jahrmarkts werden Euer sein!", completion = "Ihr habt die Dingsdas! Wunderbar! Ich kann schon jetzt das melodische Summen und Surren in meinem Kopf hören! Oh, wenn dieser Stand erst einmal fertig ist, dann wird er ein Weltwunder sein, das mich zeichnen wird!\n\nHier sind Eure Lose, {name}. Bitte amüsiert Euch auf dem Jahrmarkt!" }
quests[79592] = { id = 79592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jahrmarktswämser", progress = "Unsere Arbeiter vom Jahrmarkt machen weitaus mehr als Dreck wegzufegen und Bolzen einzuschlagen! Sie helfen auch den Jahrmarkt auf Reisen zu bewachen und benötigen dafür stets robuste und rüstungsstarke Wämser.\n\nWenn Ihr etwas strapazierfähige Rüstung herstellt und zu mir bringt, dann werde ich dies sicherlich an die richtigen Leute weiterleiten. Ich werde Euch im Austausch dafür auch ein paar Lose des Dunkelmond-Jahrmarkts geben.", completion = "Ah, Ihr habt die Wämser. Wunderbar. Darf ich fragen welches Tierleder Ihr für die Herstellung verwendet habt? Die Nähte sind erstklassig verarbeitet worden und die Struktur des Leders scheint ebenfalls sehr robust. Ihr seid ein begabter Handwerker!\n\nDankeschön, {name}, hier sind Eure Lose." }
quests[79593] = { id = 79593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grober Gewichtsstein", progress = "Es kostet einiges die stärkste Frau der Welt zu sein! Mein Gewichtsset wird langsam zu leicht für mich und wenn ich in Form bleiben möchte, brauche ich mehr Gewichte!\n\nKönnt Ihr mir vielleicht ein paar Gewichtssteine besorgen? Wenn ja, werde ich Euch ein Los des Dunkelmond-Jahrmarkts geben.", completion = "Großartig! Diese werden ihren Zweck erfüllen! Sie sind nicht zu schwer, aber auch nicht zu leicht. Sie eignen sich perfekt zum Aufbau von Muskelmasse!\n\nIch danke Euch, {name}.  Hier ist Euer Los!" }
quests[79594] = { id = 79594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kupfermodulator", progress = "Yebb arbeitet an einer neuen Attraktion für das Kuriositätenkabinett, eine, die die Leute vor Verwunderung und Erstaunen begeistern wird! Es wird allerdings eine Menge an Arbeit und bedeuten und viel Material benötigen...\n\nUnter anderem Kupfermodulatoren. Wir brauchen zahlreiche Modulatoren für die mechanischen Teile der Attraktion.  Bringt mir Kupfermodulatoren und ich werde sie gegen ein Los des Dunkelmond-Jahrmarkts einlösen.", completion = "Aha! Die Modulatoren! Herrlich!\n\nIch kann Euch zwar nicht genau sagen an was wir arbeiten, aber dies wird für dessen Konstruktion von unschätzbarem Wert sein. Ich stehe in Eurer Schuld, {name}, bitte, nehmt dieses Los des Dunkelmond-Jahrmarkts als Zeichen meiner Wertschätzung." }
quests[79595] = { id = 79595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jahrmarktsstiefel", progress = "Wir vom Dunkelmond-Jahrmarkt sind sehr viel zu Fuß unterwegs. Wir laufen von einer Attraktion zur nächsten... eigentlich werdet Ihr uns niemals während der Arbeit sitzen sehen! Es ist also nicht überraschend, dass wir viel Schuhwerk verschleißen! Wir brauchen Stiefel, die belastbar und gleichzeitig modisch sind. Geprägte Lederstiefel sind da genau das Richtige.\n\nHey! Ihr seid Lederverarbeiter, macht mir ein Paar Geprägte Lederstiefel und ich gebe Euch für Eure Arbeit ein Los des Dunkelmond-Jahrmarkts.", completion = "Danke, {name}. Eine wirklich gute Verarbeitung! Euer handwerkliches Können ist erstklassig! Hier ist Euer Los... viel Spaß damit, mein Herr." }
quests[79624] = { id = 79624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kochen kann jeder", description = "Das Rezept scheint für eine Art Fleischgericht gedacht zu sein. Es ist in einer Sprache verfasst, die Ihr nicht versteht. Vermutlich die der Oger, so schätzt Ihr, wenn man von der Quelle und Themengebiet ausgeht.\n\nOger sind nicht gerade dafür bekannt, Feinschmecker zu sein, aber wenn Ihr einen kennt, auf den das doch zutrifft, dann könnte dieser Oger das Rezept für Euch übersetzen.", sourceObjective = "Findet einen Oger, der das unleserliche Rezept entziffern kann.", completion = "Ihr habt Rezept? Skonk interessiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[79626] = { id = 79626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wiederverwertungsmat 9000!", description = "Dieser Apparat scheint mit Energie versorgt so werden, wenn auch gerade so eben. Auf einer kleinen Plakette steht: \"Der Wiederverwertungsmat 9000\", gefolgt von ein wenig Text, der nicht zu entziffern ist, da ihn eine dicke Schicht aus verkrustetem Dreck überdeckt. Die Maschine verfügt über einen riesigen Zulaufbehälter sowie einen Münzeinwurf.", sourceObjective = "Gebt ein schmutzverkrustetes Bergungsgut in den Wiederverwertungsmat 9000 und stellt sicher, dass Ihr dreißig Silbermünzen habt, um die Maschine zu aktivieren.", progress = "Die Maschine sieht aus, als bräuchte sie sehr schnell eine sehr umfassende Generalüberholung. Es scheint, als könntet Ihr weiterhin etwas schmutzverkrustetes Bergungsgut hineingeben, aber Ihr seid nicht sicher, was dann passieren wird.", completion = "Ihr füttert den Wiederverwertungsmat 9000 mit dem schmutzverkrusteten Bergungsgut sowie mit dreißig Silbermünzen. Es gehen kurz ein paar Lichter an der Maschine an, dann rüttelt und schüttelt sie sich. Anschließend spuckt sie Euer nach wie vor schmutzverkrustetes Bergungsgut aus und kommt wieder zur Ruhe. Sie scheint kaputt zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[79637] = { id = 79637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein tickendes Geschenk", sourceObjective = "Ein wundervolles Winterhauchfest wünschen Euch Eure Freunde bei Kokelwälder.", sourceObjectiveStatus = "unverified-source-field" }
quests[79677] = { id = 79677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kurzer Blick auf die Liste", description = "Andere Oger lachen über Skonk, weil Skonk kleiner als sie. Sie sagen, kleiner Oger schwach, also Skonk kochen gelernt statt kämpfen. Dadurch nur mehr Spott, also Skonk auf und davon, um Traum zu folgen.\n\nSkonk kann Gericht kochen, aber braucht Zutaten. Nicht sicher, wo sie sind. Skonk mehr Blick für Kochkunst, weniger für Beschaffung.", sourceObjective = "Sammelt die Zutaten für Skonks Gericht und bringt sie ihm im Arathihochland.", progress = "Habt Ihr Zutaten? Fast Abendessenzeit.", completion = "Gute Arbeit, {race}. Wir jetzt richtig kochen!", sourceObjectiveStatus = "unverified-source-field" }
quests[79678] = { id = 79678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschmacksprobe", description = "Gut, {race}, es Zeit für Skonks Lieblingsteil. Skonk hat Feuer lichterloh und möchte neues Gericht mit neuem Freund teilen. Ihr so große Gefallen für Skonk getan, nur richtig, dass Ihr auch was bekommt!\n\nLasst Skonk wissen, wenn bereit, zu probieren.", sourceObjective = "Probiert das Rezept mit Skonk.", completion = "Mmm, Rezept köstlich!\n\nSkonk ein bisschen verloren in Begeisterung, aber Ihr gute Hilfe!\n\nHier Euer Anteil. Skonk sogar etwas dazugegeben für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79704] = { id = 79704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wiederverwertungsmat 9000!", description = "Gebt Euer Bergungsgut in die Maschine, erhaltet im Gegenzug fantastische Preise! Wahrscheinlich. Möglicherweise.", sourceObjective = "Gebt ein schmutzverkrustetes Bergungsgut in den Wiederverwertungsmat 9000 und stellt sicher, dass Ihr drei Silbermünzen habt, um die Maschine zu aktivieren.", progress = "Die Maschine zittert und wackelt, bevor sie einen Haufen geborgene Teile ausspuckt.", completion = "Ihr füttert den Funkelmat 5200 mit dem schmutzverkrusteten Gegenstand sowie mit drei Silbermünzen. Die Maschine erwacht schlagartig zum Leben und versucht hektisch, den unbekannten Gegenstand vom Schmutz zu reinigen. Laute, heftige, peitschende Geräusche schlagen Euch aus dem Herzen der Maschine entgegen. Der Metallrahmen des Apparates knarrt und ächzt, als er hin und her schlingert...", sourceObjectiveStatus = "unverified-source-field" }
quests[79705] = { id = 79705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederverwertung des Wiederverwertungsmats", description = "Ich glaube, das Ding pfeift aus dem letzten Loch. Ich könnte es vielleicht noch mal reparieren, aber das wird nicht einfach... oder billig. Ich sag Euch was, Ihr besorgt mir 10 Mithrilbarren, 5 große Mystikeressenzen, 3 GG12-082-Sicherungseinsätze und einen makellosen G-7-K.E.R.N.-Prozessor, dann kann ich es für Euch wahrscheinlich wieder startklar machen. Die Sicherungseinsätze sollten hier in Gnomeregan einfach zu finden sein, doch so ein Prozessorkern ist ein ziemlich seltener Gegenstand und nicht ganz so leicht zu bekommen. Ihr wirkt aber recht einfallsreich, ich denke, Euch fällt da bestimmt was ein! Viel Glück!", sourceObjective = "Bringt Ziri \"Schraubenschlüssel\" 10 Mithrilbarren, 5 große Mystikeressenzen, 3 GG12-082-Sicherungseinsätze und einen makellosen G-7-K.E.R.N.-Prozessor, dann kann sie den Wiederverwertungsmat 9000 wieder auf Vordermann bringen. Wahrscheinlich. Möglicherweise.", progress = "Holla! Ihr habt diesen ganzen Schrott tatsächlich angeschleppt? Eigentlich wollte ich Euch ja bloß ein bisschen auf den Arm nehmen, aber hey, eine Gnomin, ein Wort, und ich bin niemand, der gute Materialien vor die Hunde gehen lässt. Gebt mir ein paar der Dinge und ich mach Euch das Baby hier wieder einsatzbereit!", completion = "Ein einsatzfähiger Wiederverwertungsmat 9000, ganz wie versprochen. Wenn Ihr da draußen irgendwas Tolles findet, dann kommt wieder und zeigt es mir. Möglicherweise kann ich Euch die ein oder andere Sache beibringen, für den richtigen Preis, natürlich!\n\n<Ziri grinst über beide Ohren und stopft etwas in ihre hintere Tasche.>", sourceObjectiveStatus = "unverified-source-field" }
quests[79731] = { id = 79731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Trollschriftrolle", description = "<Die uralten Glyphen werden vor Euren Augen zu Worten.>\n\nWenn der Brunnen von Zul'Kunda von den Wassern der heiligen Quelle gespeist wird, gewähren die Götter ihren Segen.", sourceObjective = "Löst das Rätsel der Schriftrolle. Sobald Ihr das getan habt, wird Hemet Nesingwary vermutlich davon hören wollen.", completion = "Ein magischer Brunnen im Dschungel? Was für eine Geschichte, {name}!\n\nDa kommt mir eine Idee für ein weiteres Kapitel in meinem Buch! Schauen wir mal, wo habe ich denn das Manuskript hingelegt...", sourceObjectiveStatus = "unverified-source-field" }
quests[79939] = { id = 79939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der kaputte Hammer", description = "Ein kaputter verzierter Kriegshammer liegt umgeben von toten Kultisten der Burning Blade und Kriegern des Scharlachroten Kreuzzugs. Hier hat sich offensichtlich vor nicht allzu langer Zeit ein Kampf zugetragen. Ihr erkennt außerdem, dass dies die Waffe eines Paladins der Silbernen Hand ist. Obwohl Ihr zahlreiche Hämmer wie diesen gesehen habt, macht ihn seine Qualität und Verarbeitung durchaus einzigartig. Ihr solltet die Umgebung nach Hinweisen absuchen und jemanden finden, der möglicherweise mehr über diese Waffe weiß.", sourceObjective = "Sucht nach Hinweisen darauf, was sich in Mannorocs Koven in Desolace zugetragen hat, und findet jemanden, der möglicherweise mehr über den kaputten Hammer weiß.", progress = "Was habt Ihr da bei Euch, mein Freund?", completion = "<Katharina seufzt schwer.> Ja, {name}, ich kenne diese Waffe. Ich nahm an, ihr Besitzer wäre bereits vor langer Zeit gestorben.", sourceObjectiveStatus = "unverified-source-field" }
quests[79940] = { id = 79940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verlorener Bruder", description = "<Katharina zuckt zusammen, als sie die zerschmetterten Fragmente des kaputten Hammers aufhebt.>\n\nIch werde nicht zu viele Einzelheiten über denjenigen teilen, der diese Waffe führte, da mich das Gesagte mit Scham erfüllen würde, aber ich erzähle Euch, was ich kann.", sourceObjective = "Sprecht mit Katharina der Reinen und bringt mehr über den kaputten Hammer in Erfahrung.", completion = "Es bieten sich Euch nicht viele Hinweise, weshalb es sich als schwierig erweisen könnte, Aeonas zu finden, doch Ihr solltet es versuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79945] = { id = 79945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehle des Obersten Kreuzzüglers", description = "Dies scheinen die Befehle des Obersten Kreuzzüglers selbst zu sein, Dathrohan. Anscheinend ist Aeonas mit dem Kreuzzug aneinandergeraten. Wenn wir aus dem Rückschlüsse ziehen wollen, was wir vor uns sehen, dann sieht es so aus, als hätte der Kreuzzug Aeonas bis hierher verfolgen und ihn stellen können. Er hat er sich offenbar nicht kampflos ergeben.\n\nEs sind ernste Vorwürfe, die gegen Aeonas erhoben wurden. Aber das würde einiges von dem erklären, was Ihr in Desolace gesehen habt.", sourceObjective = "Bringt die Befehle des Obersten Kreuzzüglers zurück zu Katharina der Reinen.", progress = "Bringt Ihr Nachricht von Aeonas?", completion = "<Katherinas Stirn legt sich in tiefe Falten, während sie den Brief liest.>\n\nAeonas vertrat ein paar radikale Ansichten, als er den Orden verließ, aber es fällt mir schwer zu glauben, dass seine Aktivitäten in Desolace den Umgang mit Dämonen oder Untoten eingeschlossen haben sollen. Wir müssen ihn finden und uns seine Version der Geschichte anhören. Ich bin mir sicher, dass hinter der ganzen Sache noch mehr steckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[79946] = { id = 79946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Bruder in Not", description = "Aufgrund der... unglücklichen Umstände, unter denen er den Orden verließ, wäre es wahrlich ein schlechter Witz, wenn Aeonas nun durch die Hand des Scharlachroten Kreuzzugs sterben würde. Der Kreuzzug ist eine Organisation von Fanatikern und Wahnsinnigen, und ihre Gewalt gegenüber allen, die sie als Feinde des Lichts betrachten, hat immer unverfrorenere Züge angenommen. Geht zum Scharlachroten Kloster in Tirisfal und findet Aeonas, wenn er denn noch am Leben ist.", sourceObjective = "Sprecht mit Katharina, um mehr über Aeonas zu erfahren und findet ihn dann im Scharlachroten Kloster.", completion = "<Aeonas scheint ernsthaft verwundet zu sein. Es fällt ihm schwer, ein paar Worte zu sprechen.> Sie haben... mir gar keine Fragen gestellt...", sourceObjectiveStatus = "unverified-source-field" }
quests[79947] = { id = 79947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geomantie: Der steinige Weg zur Wahrheit", progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, {name}. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte." }
quests[79948] = { id = 79948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Einmaleins der Verteidigungsmagie", progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, {name}. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte." }
