quests[79953] = { id = 79953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anleitung zur Pflege eines dämonischen Begleiters für Anfänger", progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, {name}. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte." }
quests[79963] = { id = 79963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bei der Anmut des Lichts", description = "Aeonas bedarf sofortiger Heilung, sonst stirbt er. Ruft das Licht an und rettet ihn.", sourceObjective = "Heilt Aeonas.", completion = "<Aeonas scheint das Atmen leichter zu fallen. Er wirkt immer noch sehr schwach, aber er schafft es, Euch seinen Kopf zuzuwenden, um zu sprechen.>\n\nIhr sagt, dass Katherina Euch schickt? Gesegnet sei sie. Ich danke Euch, {class}. Ich stehe in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[79970] = { id = 79970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aeonas der Verteidigte", description = "Danke, dass Ihr mich gerettet habt, {class}. Es scheint, als wäre ich nicht mehr ganz so jung, wie ich es einst war. Und es scheint auch, als würde ich für das, was noch kommt, einige Verbündete brauchen. Trefft mich, sobald Ihr könnt, in Stormwind bei der Kathedrale des Lichts.\n\nMacht Euch um mich keine Sorgen, ich finde schon selbst den Weg zurück. Ich brauche nur einen Moment, um wieder zu Kräften zu kommen.", sourceObjective = "Trefft Euch mit Aeonas an der Kathedrale des Lichts in Stormwind.", completion = "Ich kann Euch nicht genug danken, dass Ihr mich aus diesem lichtverlassenen Ort gerettet habt. Leider glaube ich, dass das erst der Anfang unserer Reise war und der Rest nicht leichter wird. Unterhalten wir uns und planen wir unsere nächsten Schritte.\n\nOh, zuallererst jedoch... erlaubt diesem alten Mann, etwas von seinem Wissen an die jüngere Generation weiterzugeben. Es ist keine große Belohnung, doch ich hoffe, dass es sich Euch dennoch als nützlich erweist.", sourceObjectiveStatus = "unverified-source-field" }
quests[79974] = { id = 79974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuchte Angelegenheit", description = "Ich habe gerne einen Reservevorrat in der Nähe, falls ich mich doch mal schnell aus dem Staub machen muss.\n\nDas Antlitz dieses Berghangs ist so wunderschön, man könnte sagen, dass es aus den Wasserfällen der Zeit geschnitzt wurde.\nDas ist der Adlerhorst, der Ort, nach dem Ihr sucht.", sourceObjective = "Beim Abstauben einer vom Boden aufgelesenen Kuriertasche findet Ihr zwischen den Vorräten ein Pergament.", completion = "Die Ingenieurskunst der Zwerge, ein Wunderwerk wie eh und je.", sourceObjectiveStatus = "unverified-source-field" }
quests[79975] = { id = 79975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adlerfaust", description = "Ihr findet einen sorgfältig gefalteten Brief im Werkzeugkasten. Ihr stellt Euch eine Stimme vor und lest: \"Von hier aus habt Ihr das Sagen, vorausgesetzt, Ihr habt das richtige Werkzeug. Das ist ein toller Ort, um einen Paragleiter zu starten.\n\nMeine Loyalität zu Adler und Faust benötigt Distanz, um ihnen so gut wie möglich zu dienen. Diese Barrikade hat schon bessere Tage gesehen, genau wie die Alten Königreiche, die sie einst verteidigt hat, aber ich werde sie nie verlassen.\"", sourceObjective = "Spritzendes Wasser befeuchtet die Luft, der Ausblick ist unglaublich.", completion = "Ein Lagerfeuer, bei dem vor Kurzem Holz nachgelegt wurde. Es gibt deutliche Anzeichen eines zügigen Aufbruchs.", sourceObjectiveStatus = "unverified-source-field" }
quests[79976] = { id = 79976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das muss der Ort sein", description = "\"Ich habe mich dazu entschlossen, meine Arbeit wieder unter Tage weiterzuführen, damit sie auch ja nicht in die falschen Hände gerät.\"\n\nDas Papier wurde so abgerissen, dass die Nachricht gerade so darauf Platz findet. Ihr seid Euch nicht sicher, ob das die letzten Worte sind, die Ihr vom Verfasser lesen werdet, oder ob sie ein Hinweis auf das nächste Versteck sind. Ein unzureichend gesicherter Schlafsack rollt sich vor Euren Füßen aus...", sourceObjective = "Wer auch immer hier war, Ihr habt die Person nur knapp verpasst.", completion = "Allerlei Gerätschaften befinden sich versteckt unter einer schweren Plane. Ihr bedient Euch am Gepäck.", sourceObjectiveStatus = "unverified-source-field" }
quests[79980] = { id = 79980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg hier", description = "Gar nicht so übel, was? Dass Ihr das lest, bedeutet, dass mein Vorrat immer noch da ist. Geht hundert Schritte nach Norden und brecht Euch nicht die Beine, wenn Ihr die steile Klippe hinuntersteigt. Das sollte genügen, um Euch auf der Spur zu halten.", sourceObjective = "Findet, was Euch erwartet.", completion = "Ihr zieht eine Kuriertasche aus dem Boden. Neben den Vorräten findet Ihr darin auch ein schmutziges Pergament.", sourceObjectiveStatus = "unverified-source-field" }
quests[79981] = { id = 79981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der korrodierte Kern", description = "Diese K.E.R.N.-Einheit passt definitiv zu der Beschreibung, die Ziri Euch gegeben hat, doch sie ist schwer beschädigt und verdreckt. Ihr könnt gerade so ein verblasstes Etikett ausmachen, auf dem sich allem Anschein nach die Kontaktinformationen für eine Art Garantie befinden. Es lassen sich nur ein paar wenige Buchstaben ausmachen.\n\n\"Beschr... ...rantieanspruch: Bit... ...enden Sie ...ich an Wi... ...nder...ad\"", sourceObjective = "Findet jemanden, der den korrodierten G-7-K.E.R.N.-Prozessor reparieren kann.", progress = "Wenn jemand einen Turm und eine Werkstatt auf einer gewaltigen Spitze mitten im Nirgendwo baut, könnte man fast meinen, dass die Person keine unerwarteten Besucher wünscht. Wer hätte es gedacht?", completion = "<Wirdals Vergrößerungsbrille gibt ein tiefes, mechanisches Surren von sich, während sie sich auf den korrodierten G-7-K.E.R.N.-Prozessor in Eurer Hand fokussiert.> Tatsache, das ist einer von meinen.\n\nIch rate Euch dringend, das Ding ins Meer zu schmeißen und keinen weiteren Gedanken daran zu verschwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[79982] = { id = 79982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garantieanspruch", description = "Ich kann den Prozessor für Euch reparieren, doch dafür brauche ich einen Gegenstand, der eher schwer in die Finger zu kriegen ist: einen aufgeladenen Leerenkern. Nagazauberer sollen die gerne bei sich tragen. Ich bin mir nicht ganz sicher, wo die Naga sie herbekommen oder wie sie hergestellt werden, doch sie werden oft als mächtige Fokusse für bestimmte Arten von magischen Ritualen verwendet. Sie sind die Schlüsselkomponente für meine G-7-K.E.R.N.-Prozessoreinheit. Sie sind aber auch nicht sehr geläufig, es wird also kein Leichtes, einen aufzutreiben.", sourceObjective = "Bringt Wirdal Wunderrad einen aufgeladenen Leerenkern.", progress = "Ich will gar nicht erst wissen, wie viele Naga Ihr vermöbeln musstet, um an das Teil zu gelangen.", completion = "Nun, wird schon schiefgehen.\n\nIch sehe mich dazu veranlasst, Euch darüber zu informieren, dass ich für keinerlei elektrische Brände, elektromagnetische Impulsexplosionen, dämonische Manifestationen oder interdimensionale Strudel hafte, die sich durch Installation und Verwendung dieses Prozessors ergeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[79984] = { id = 79984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quadrangulation", description = "Wirdal? Ja, den kenne ich. Ist ein Gnom, aber das kreide ich ihm nicht an, schließlich ist er genau wie ich ebenfalls ein bekennender Liebhaber von Transpolyportationen. Er hat sich vor ein paar Monaten von hier verabschiedet und sich was irgendwo in Kalimdor gesucht, doch hin und wieder portet er vorbei und schnappt sich ein paar Vorräte. Ich könnte Euch vermutlich zu ihm transpolyportieren, doch dafür bräuchten wir seine Koordinaten, sonst teleportiere ich Euch noch in einen Berg oder so. Wenn Ihr seine Quadrangulationssignalgeber in Kalimdor aufspürt und Euch auf diese einstimmt, könnte das funktionieren!", sourceObjective = "Findet Wirdal Wunderrads Quadrangulationssignalgeber und stimmt Euch auf sie ein. Es gibt vier von ihnen und sie befinden sich irgendwo in Kalimdor.", completion = "Wow, Ihr habt sie gefunden. Gebt mir einen Moment, ich muss nur die Koordinaten eingeben und den Transponder kalibrieren...\n\n...und schon haben wir's! Ich glaube, das könnte sogar funktionieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[79985] = { id = 79985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine schöne Bescherung", description = "<Kernobee stöhnt.> Was... Was ist passiert?\n\nDas Letzte, an das ich mich erinnere, ist, wie ich von einer Gruppe Dunkeleisenzwerge gefangen, halb tot geprügelt und dann hier zu diesen schmutzigen Troggs geworfen wurde.\n\nHolt mich hier raus, {name}!\n\nSo ist der Plan: Bringt mich zum Ausgang. Wenn wir es lebend hier herausschaffen, geht nach Booty Bay und lasst Scooty wissen, dass ich nach Ratchet gegangen bin, um Tinkerwiz zu warnen, dass die Dunkeleisenzwerge in die Herstellung dieser Supermaschine verwickelt sind.\n\nGehen wir!", sourceObjective = "Begleitet Kernobee zur Uhrwerkgasse und meldet Euch dann wieder bei Scooty in Booty Bay.", completion = "Ich schätze, Ihr solltet dafür belohnt werden, Kernobee in einem Stück zurückgebracht zu haben, {name}. Wenn Ihr nach Gnomeregan zurückkehrt, könnten diese hier Euch den entscheidenden Vorteil liefern, den Ihr benötigt, um diesen nichtsnutzigen Verräter Robogenieur Thermaplugg zu besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79986] = { id = 79986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmutzverkrusteter Ring", description = "Ihr habt bei einer der Leichen der Dunkeleisenzwerge etwas entdeckt, das wie ein Ring aussieht. Es ist jedoch schwer zu sagen, was für ein Ring das ist. Das Ding ist derart mit Dreck und Verkrustungen überzogen, dass man es unmöglich an einen Finger stecken kann. Ihr glaubt, unter den Verkrustungen Edelmetall schimmern und vielleicht sogar einen Edelstein glitzern zu sehen.\n\nWenn Ihr diesen Ring verwenden wollt, müsst Ihr nach etwas suchen, das die Verkrustungen entfernt.", sourceObjective = "Findet einen Weg, den schmutzverkrusteten Ring zu säubern.", progress = "Der Gnomenapparat vor Euch trägt eine Plakette mit der Aufschrift \"Der Funkelmat 5200\". Laut der Anleitung unter der Plakette besteht der Sinn dieser Maschine darin, jedweden Schmutz von Gegenständen abzuschrubben. Um den Vorgang zu starten, legt man den Gegenstand in die Maschine und wirft drei Silbermünzen in den Münzschlitz.\n\nEs scheint, als sei der verkrustete Ring, den Ihr gefunden habt, geradezu perfekt, um diese Maschine auszuprobieren.", completion = "Ihr legt den Ring in den Funkelmat 5200 und werft eine Silbermünze in den Schlitz.\n\nFurchtbares Knirschen und Mahlen dringt aus der Maschine, als sie heftig zu ruckeln beginnt. Man kann nur raten, was mit dem Ring in der Maschine passiert...\n\nDann stoppt die Maschine plötzlich, ihren Stillstand mit einem einfachen \"Ding!\" verkündend. Der Aufnahmebehälter öffnet sich und offenbart eine kleine, hübsch verpackte Schachtel mit einer roten Schleife. Es scheint, als würde der Funkelmat 5200 alles auch gleich noch als Geschenk verpacken!", sourceObjectiveStatus = "unverified-source-field" }
quests[79987] = { id = 79987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr des Rings", description = "Ihr öffnet die Schachtel, die der Funkelmat 5200 ausgegeben hat, und entdeckt, was Ihr vermutet hattet - einen glänzenden Ring! Beim Anstecken des Rings fühlt Ihr magische Macht durch Euren Körper fließen.\n\nAuf der Innenseite des Rings befindet sich eine kleine, aber dennoch klar erkennbare Gravur des Siegels von Ironforge. Daneben sind drei kleine Initialen eingraviert: \"TdK\". Dies könnten entweder die Initialen des ursprünglichen Besitzers oder die des Herstellers des Rings sein. Den Ring behalten...oder ihn dieser Person zurückgeben? Entscheidungen über Entscheidungen...", sourceObjective = "Ihr könnt den Ring entweder behalten oder die Person finden, die für die Prägung und Gravuren auf der Innenseite des Rings verantwortlich ist.", progress = "He, immer mit der Ruhe, Partner - ich bin ein wichtiger Geschäftsmann! Der Kurier, der die Miete überbringen sollte, ist bestimmt einfach nur spät dran... Moment mal... Ihr seid ja gar nicht mein Vermieter.\n\nNatürlich seid Ihr das nicht - wie dumm von mir! Ihr seid hier, weil Ihr den besten Juwelier in ganz Ironforge sucht, einen, der KEINE VERFLUCHTEN Gegenstände herstellt. Jawohl!\n\nHm... Was braucht Ihr?", completion = "Ein Ring, sagt Ihr? Lasst mich mal sehen... Ja, und wie ich diesen Ring gefertigt habe.\n\nBevor Gnomeregan verloren ging, hatte ich dort einen kleinen Laden. Vielleicht ist es einer von denen, die ich zurückließ, als ich in die Hügel geflohen bin. Er ist recht schlicht gehalten und ich habe mehrere dieser Art hergestellt. Vielleicht gehörte er auch jemandem, der es nicht bis nach draußen geschafft hat.\n\nDunkeleisenzwerge hatten ihn? Tja, das fügt den ganzen Verschwörungstheorien, die bereits herumgeistern, eine weitere Ebene hinzu. Vielleicht interessieren sich offizielle Stellen dafür. Für Leute wie mich ist so etwas unwichtig.\n\nAber jetzt zurück zu diesem Ring...", sourceObjectiveStatus = "unverified-source-field" }
quests[79990] = { id = 79990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holz aus dem Schlingendorntal", description = "Wir suchen händeringend nach weiteren Ressourcen und Verstärkungen, um unsere Ziele im Arathibecken zu erreichen. Insbesondere Holz ist fast unmöglich zu bekommen und wir sind gezwungen, bis ganz zum Schlingendorntal zu blicken, um das zu besorgen, was wir brauchen. Bringt mir eine Lieferung Schlingendornholz und Eure Unterstützung wird nicht unbemerkt bleiben.", sourceObjective = "Beschafft Sergeant Maclear eine Lieferung Schlingendornholz.", progress = "Habt Ihr frische Vorräte für uns?", completion = "Habt Dank, {class}. Das wird uns helfen, das Blatt im Arathibecken zu wenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[79991] = { id = 79991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holz aus dem Schlingendorntal", description = "Wir suchen händeringend nach weiteren Ressourcen und Verstärkungen, um unsere Ziele im Arathibecken zu erreichen. Insbesondere Holz ist fast unmöglich zu bekommen und wir sind gezwungen, bis ganz zum Schlingendorntal zu blicken, um das zu besorgen, was wir brauchen. Bringt mir eine Lieferung Schlingendornholz und Eure Unterstützung wird nicht unbemerkt bleiben.", sourceObjective = "Beschafft Todespirscher Mortis eine Lieferung Schlingendornholz.", progress = "Habt Ihr frische Vorräte für uns?", completion = "Habt Dank, {class}. Das wird uns helfen, das Blatt im Arathibecken zu wenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[80001] = { id = 80001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neu entfachen", progress = "Eine erloschene Feuerstelle. Das Holz ist sogar trocken genug, um eine Flamme zu entzünden.", completion = "Ihr setzt Eure Späherfähigkeiten ein." }
quests[80098] = { id = 80098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eigentümliches Relikt aus Dalaran", progress = "Habt Ihr eines der gestohlenen Relikte geborgen?", completion = "Vielen Dank, {name}. Ich werde dafür sorgen, dass es seinen Weg in die Stadt sicher zurückfindet." }
quests[80120] = { id = 80120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dienst für Dalaran", sourceObjective = "Ihr habt Dalaran und Azeroth einen großen Dienst erwiesen.\n\nUnsere Gesetze verbieten es mir, die Geheimnisse Dalarans mit Außenstehenden zu teilen, aber ich denke, ich kann die Regeln ein wenig beugen, um Euch für Eure Bemühungen zu entlohnen. Bitte nehmt dies.", sourceObjectiveStatus = "unverified-source-field" }
quests[80131] = { id = 80131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomenverbesserungen", description = "Hört mir zu, {name}. Dieser Ring gehört Euch, das ist schon richtig... aber ich kann Euch einen besseren machen! Das Design ist, wie ich bereits sagte, wirklich einfach. Ich bin heutzutage wesentlich geschickter und für die läppische Summe von dreißig Silbermünzen werde ich ihn für Euch aufpeppen! Na ja, eigentlich etwas mehr als dreißig...\n\nIch bin derzeit in einer misslichen Lage. Mein ganzer Materialvorrat ist aufgebraucht. Wenn Ihr mir einen Barren Silber und einen Moosachat bringt, verziere ich Euch den Ring damit und peppe ihn richtig schön auf!!\n\nVertraut mir!", sourceObjective = "Bringt Talvash del Kissel in Ironforge den blitzenden Goldring, einen Silberbarren, einen Moosachat und 30 Silbermünzen.", progress = "Habt Ihr die Materialien, die ich benötige? Ich würde Euch nicht darum bitten, wenn ich nicht gerade völlig vom Glück verlassen wäre...", completion = "Ah, genau das, was ich brauchte! Eines Tages, wenn ich es aus diesem Loch, in dem ich mich ungerechterweise befinde, herausgearbeitet habe, werde ich für Euch, nein für JEDERMANN die besten Schmuckstücke in ganz Azeroth herstellen! Bis es so weit ist, danke ich Euch, dass Ihr in Bezug auf die Reagenzien so anständig wart. Ich würde normalerweise zehnmal so viel für einen Ring von dieser Qualität verlangen, wie ich Euch abgeknöpft habe...\n\nWo wir gerade davon sprechen, hier ist Euer neuer Ring!", sourceObjectiveStatus = "unverified-source-field" }
quests[80132] = { id = 80132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maschinenkriege", description = "Vor zwei Jahren noch hat man sich jedes Mal darüber lustig gemacht, wenn die Rede auf Gnomentechnologie kam. Diese Zeiten haben sich definitiv geändert. Jetzt haben sie eine neue Maschine gebaut, die besser ist als all unsere Schreddermodelle zusammen. Ich brauche die Blaupausen dafür, {name}!\n\nDummerweise sind die Pläne in einem Safe bei Robogenieur Thermaplugg sicher verwahrt. Was die Sache noch erschwert: Nur Robogenieur Thermaplugg kennt die Kombination zu diesem Safe.\n\nTut, was Ihr tun müsst, um diese Kombination zu erlangen, {name}. Dann öffnet den Safe und bringt mir diese Blaupausen!", sourceObjective = "Besorgt die Maschinenblaupausen und Thermapluggs Safekombination aus Gnomeregan und bringt sie zu Nogg nach Orgrimmar.", progress = "Ich sehe keine Blaupausen. Habt Ihr sie irgendwo unter Euren Kleidern versteckt oder steht Ihr hier nur rum, um mir auf die Nerven zu gehen?", completion = "Ich wusste, Ihr könnt es schaffen, {name}! Sovik wiederum hatte seine Zweifel.\n\n\n\nJetzt, da wir die Blaupausen besitzen, ist es nur noch eine Frage der Zeit, bis wir alle Gnomeninnovationen enträtselt haben, die beim Bau dieser Maschine gemacht wurden, und sie zu Goblininnovationen für unsere neuen Schreddermodelle machen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[80133] = { id = 80133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chefingenieur Scooty", description = "In dem Moment, als wir durch Kernobee von der neuen Gnomenmaschine hörten, haben Scooty und ich mit der Arbeit am Transpolyporter 6000 begonnen: dem schnellsten und verlässlichsten Weg nach Gnomeregan.\n\nEndlich ist er bereit, Passagiere aufzunehmen, {name}. Wenn Ihr es einmal versuchen wollt, geht nach Booty Bay und redet mit Scooty am Windreiterhorst. Um nach Booty Bay zu gelangen, nehmt das Boot von Ratchet aus.\n\nNatürlich könnt Ihr auch versuchen, Euch durch die von Zwergen verseuchten Berge von Dun Morogh nach Gnomeregan durchzuschlagen!", sourceObjective = "Sprecht mit Scooty in Booty Bay.", completion = "Ist sie nicht eine Schönheit? Ein Meisterstück der Goblintransporttechnologie - ist nur ein Dutzend Mal oder so explodiert.\n\nKeine Sorge, {name}, ich habe sie vollständig repariert. Sie wird Euch nicht um die Ohren fliegen - und falls doch, dann wird es schnell und schmerzlos sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[80134] = { id = 80134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomer-weeeeg!", description = "Solange Ihr den Transponder bei Euch habt, müsst Ihr lediglich auf diese Plattform hier treten und Ihr werdet nach Gnomeregan teleportiert.\n\nIhr werdet vielleicht ein paar ungewöhnliche Nebenwirkungen erleben, aber keine davon sollte dauerhaft sein... zumindest nicht mehr.\n\nIch hätte fast den wichtigsten Teil vergessen - die Rückkehr. Wenn Ihr wieder zurückkommen wollt, tretet einfach auf die Transpolyporter-Plattform in Gnomeregan!\n\nJetzt lasst uns diesen Transponder auf Euer Gewicht und Eure Größe einstellen.", sourceObjective = "Wartet, bis Scooty den Goblintransponder kalibriert hat.", completion = "Das war's! Wenn Ihr so weit seid, tretet einfach auf die Plattform.", sourceObjectiveStatus = "unverified-source-field" }
quests[80135] = { id = 80135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klockmorts Grundlagen", description = "Ein Gnomenfreund, Klockmort Spannerspan, hat mich aus Ironforge kontaktiert. Er teilt mir mit, dass er Hilfe bei einer gefährlichen, aber unverzichtbaren Mission nach Gnomeregan braucht, der einst so großen Gnomenstadt, die jetzt verseucht und voller verrückter Gnome und ihrer Gerätschaften ist.\n\nIch muss hierbleiben, aber mir blutet das Herz, wenn ich meinem Freund nicht helfen kann. Wenn Ihr an meiner Stelle gehen könnt, dann stünde ich tief in Eurer Schuld.\n\nIhr könnt Klockmort in Tüftlerstadt in Ironforge finden.", sourceObjective = "Sprecht mit Klockmort Spannerspan in Ironforge.", completion = "Allerdings! Ich brauche Hilfe bei einer Mission, die nach Gnomeregan hineinführt. Und Ihr seid genau der {class}, der das tun könnte!", sourceObjectiveStatus = "unverified-source-field" }
quests[80136] = { id = 80136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grundlegende Artifixe", description = "Ein beinahe universell einsetzbares mechanisches Bauteil - das grundlegende Artifix - war den Tüftlern und Schmieden von Gnomeregan von großem Nutzen. Doch während der panischen Flucht aus unserer Stadt hat niemand daran gedacht, einige von diesen Geräten mitzunehmen! Und ich brauche eine ganze Menge davon für eine Arbeit, die ich in Kürze in Angriff nehmen werde.\n\nBitte, geht nach Gnomeregan und bringt mir einige grundlegende Artifixe. Ihr werdet sie in den tieferen Bereichen unserer Stadt finden, in \"Künstliche Extrapolatoren\" genannten Behältern.\n\nDanke, {name}, und bitte beeilt Euch!", sourceObjective = "Bringt Klockmort Spannerspan in Ironforge 12 grundlegende Artifixe.", progress = "Habt Ihr die grundlegenden Artifixe?", completion = "Ihr habt sie! Jetzt kann ich mit meinen neuen Experimenten beginnen!\n\nIch kann Euch gar nicht genug danken, {name}! Durch Eure Tapferkeit hat die Gnomenforschung einen riesigen Schritt nach vorn gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[80137] = { id = 80137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet Techbots Hirn!", description = "Als unsere geliebte Stadt Gnomeregan fiel, muss ein verirrter Funke mein armes Geschöpf, Techbot, völlig durcheinandergebracht haben. Früher half er mir und meinen Kollegen mit seinen zahllosen Dingsdas und seiner endlosen Speicherkapazität, aber sein positronisches Gehirn wurde polarisiert. Es ist jetzt negatronisch... und Techbots Verhalten wurde umgekehrt. Er wütet jetzt in ganz Gnomeregan!\n\nDoch vielleicht kann man ihn noch retten. Wenn Ihr seinen Speicherkern auffinden und zu mir bringen könnt, kann ich die Ursache der Polarisierung möglicherweise finden und meinen armen Techbot reparieren.", sourceObjective = "Bringt Techbots Speicherkern zu Tüftlermeister Overspark nach Ironforge.", progress = "Habt Ihr Techbot gefunden? Habt Ihr seinen Speicherkern gefunden?", completion = "Oh, das ist wunderbar!! Danke, {name}! Ich mache mich gleich an die Arbeit!!\n\nArmer, armer Techbot... Mach dir nichts daraus. Wir kriegen dich wieder hin.\n\nHm, wo hab ich diesen Aufsatz für meine Hydrowinden-Ratsche hingelegt...", sourceObjectiveStatus = "unverified-source-field" }
quests[80138] = { id = 80138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tüftlermeister Overspark", description = "Tüftlermeister Overspark ist ob des Schicksals seiner mechanischen Schöpfung, Techbot, ziemlich bestürzt. Ich erinnere mich an Techbot als ein freundliches und hilfsbereites Werkzeug der Gnome, aber Overspark erzählte mir, er hätte eine Fehlfunktion.\n\nWirklich traurig. Aber mit etwas Glück kann er vielleicht repariert werden!\n\nSprecht mit Tüftlermeister Overspark in Tüftlerstadt, Ironforge. Er würde sich über Eure Hilfe freuen.", sourceObjective = "Sprecht mit Tüftlermeister Overspark in Ironforge.", completion = "Ja, es ist wahr. Techbot ist durchgedreht! Könnt Ihr mir bitte helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[80139] = { id = 80139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnogaine", description = "Seit dem Unfall redet Gnoarn nur noch davon, Gnomeregan vom Troggbefall zu befreien und ein Heilmittel für die Erkrankung, die die Stadt verseucht, zu finden, {name}.\n\nZum Glück sind Razzle und ich gerade dabei, ein solches Heilmittel zu entwickeln... oder vielleicht auch ein Rezept für wirklich starken Rum. Genau wissen wir das aber erst, wenn wir es ausprobiert haben! Logischerweise benötigen wir zum Test unserer Theorie ein paar Dinge, vor allem Ablagerungen von den bestrahlten Troggs in Gnomeregan. Füllt diese Phiole mit dem grünen Leuchten und bringt sie zurück!", sourceObjective = "Sammelt mit der leeren bleiernen Sammelphiole radioaktive Ablagerungen bestrahlter Eindringlinge oder Plünderer. Sobald sie voll ist, bringt Ihr sie zu Ozzie Togglevolt nach Kharanos zurück.", progress = "Seht Ihr denn nicht, dass wir versuchen, ein ganzes Gnomenvolk zu heilen?! Wir brauchen mehr von dem grünen Leuchten!", completion = "Ausgezeichnete Arbeit! Es ist an der Zeit, die neue Formel zu testen. Wenn sie funktioniert, sollte nicht nur dieser gefangene Lepragnom bald geheilt sein, sondern ich auch wieder ordentlich Haare auf dem Kopf haben. Tretet zurück!", sourceObjectiveStatus = "unverified-source-field" }
quests[80140] = { id = 80140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr des Rings", description = "Ihr öffnet die Schachtel, die der Funkelmat 5200 ausgegeben hat, und entdeckt einen glänzenden Ring! Beim Anstecken des Rings fühlt Ihr magische Macht durch Euren Körper fließen.\n\nAuf der Innenseite des Rings befindet sich eine kleine, aber dennoch klar erkennbare Gravur des Siegels von Orgrimmar. Daneben sind Buchstaben eingraviert, aber selbst nach der Säuberung sind nur die ersten drei zu erkennen: 'NOG...'\n\nDies könnten entweder die Initialen des ursprünglichen Besitzers oder die des Herstellers des Rings sein. Den Ring behalten...oder 'NOG' suchen - Entscheidungen, Entscheidungen...", sourceObjective = "Ihr könnt den Ring entweder behalten oder die Person finden, die für die Prägung und Gravuren auf der Innenseite des Rings verantwortlich ist.", progress = "Man sollte meinen, wir finden selbst einen Weg, diese dreckigen kleinen Gnome zu übertrumpfen. Ich würde sogar wetten, dass sie uns diese Maschine ursprünglich gestohlen haben! Pah, diese schleimigen, schmutzigen... ähm, ja? Braucht Ihr etwas?", completion = "Ein Ring aus Gnomeregan? Lasst mich mal sehen... nicht von mir, aber interessant.\n\nDiese Sache mit Gnomeregan - das hätte keinen größeren Trotteln passieren können. Jahrelang sind sie ein Witz und auf einmal bauen sie quasi über Nacht bessere Maschinen als wir?\n\nDunkeleisenzwerge hatten den Ring bei sich? Das wird ja immer interessanter! Hmmm, vielleicht haben die Gnome ja deren verrückte Golempläne gestohlen und verändert... Diese Dunkeleisenzwerge, die würden ihnen das bestimmt gern ordentlich heimzahlen. Es lohnt sich ganz sicher, da mal nachzuforschen.\n\nUnd da ist schließlich die Sache mit dem Ring...", sourceObjectiveStatus = "unverified-source-field" }
quests[80141] = { id = 80141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noggs Ringerneuerung", description = "Nein, nein, nein - ich behaupte nicht plötzlich, der Ring sei meiner. Normalerweise mache ich so etwas nicht, aber Eure Information über die Dunkeleisenzwerge war sehr nützlich. Ich werde diesen Ring für Euch so verbessern, dass selbst der, der dieses einfache kleine Ding hergestellt hat, es nicht hätte besser machen können. Wahrscheinlich war es irgendein Gnom...\n\nWenn Ihr mir einen Barren Silber, einen Moosachat und dreißig Silbermünzen bringt, verziere ich den Ring damit derart, dass seine Magie noch verstärkt wird. Interessiert?", sourceObjective = "Bringt Nogg in Orgrimmar den blitzenden Goldring, einen Silberbarren, einen Moosachat und 30 Silbermünzen.", progress = "Habt Ihr die Materialien, die ich benötige? Ich kann dieses Stück nicht ohne die Dinge verbessern, um die ich Euch gebeten habe.", completion = "Hier habt Ihr Euren Ring, besser als je zuvor. Danke nochmals für die Information über diese Dunkeleisenzwerge. Das sieht nach einem vernünftigen Hinweis darauf aus, woher diese Gnome auf einmal mit Inspiration nach Goblinart gesegnet wurden.", sourceObjectiveStatus = "unverified-source-field" }
quests[80142] = { id = 80142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Castpipes Auftrag", description = "Mechanikermeister Castpipe in Ironforge sucht Abenteurer! Er organisiert Teams, um Gnomeregan auf einer Datensicherungsmission höchster Sicherheitsstufe und Wichtigkeit zu betreten.\n\nCastpipe mag zwar nicht wie ich ein Mitglied der Erleuchteten Vereinigung für Arkanologie, Alchemie und Ingenieurwissenschaften sein, aber er ist dennoch ein kluger Gnom, und wenn er es für wichtig hält, dann besteht nach meinen Berechnungen eine vierundachtzigprozentige Wahrscheinlichkeit, dass es wirklich wichtig ist.\n\nDas ist eine gute Chance!", sourceObjective = "Sprecht mit Mechanikermeister Castpipe in Ironforge.", sourceObjectiveStatus = "unverified-source-field" }
quests[80143] = { id = 80143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Datenrettung", description = "Als wir aus Gnomeregan flohen, haben wir so viele Daten zurückgelassen! Lebenswichtige Informationen!\n\nIch brauche die Daten auf einer Prismalochkarte aus einem Matrix-Prägographen 3005-D, einem Hochsicherheitsterminal, tief in Gnomeregan. Ihr müsst auf dieses Terminal zugreifen, aber dafür braucht Ihr die Zugangsberechtigung...und um die zu erhalten, müsst Ihr erst Zugang zu den Terminals niedrigerer Sicherheitsstufen - Modelle A, B und C - haben. DAFÜR wiederum braucht Ihr Sicherheitslochkarten, angefangen mit einer weißen...Und wir haben alle Lochkarten in der Stadt vergessen.\n\nDas ist eine Katastrophe! Könnt Ihr helfen?", sourceObjective = "Bringt Mechanikermeister Castpipe in Ironforge eine Prismalochkarte.", progress = "Habt Ihr die Prismalochkarte?", completion = "Ihr habt es geschafft! Ihr habt die Prismalochkarte gefunden und die verlorenen Daten wiederbeschafft! Lebenswichtige, kritische, unvorstellbar wertvolle Daten, ohne die wir keine Minute länger hätten leben können!\n\nDer Dienst, den Ihr den Gnomen erwiesen habt, wird lange in Erinnerung bleiben, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[80147] = { id = 80147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eigentümliches Relikt aus Dalaran", progress = "Habt Ihr eines der gestohlenen Relikte geborgen?", completion = "Vielen Dank, {name}. Ich werde dafür sorgen, dass es seinen Weg in die Stadt sicher zurückfindet." }
quests[80148] = { id = 80148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eigentümliches Relikt aus Dalaran", progress = "Habt Ihr eines der gestohlenen Relikte geborgen?", completion = "Vielen Dank, {name}. Ich werde dafür sorgen, dass es seinen Weg in die Stadt sicher zurückfindet." }
