quests[80170] = { id = 80170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festtagsmuster", progress = "Die Kleider und Hosenanzüge, die Ihr hier sehen könnt, sind traditionelle Gewänder vergangener Zeiten. Sie werden zu Ehren alter Gebräuche und geliebter Vorfahren getragen.\n\nBringt Ihr mir Münzen der Urahnen, {name}, werde ich Euch das Muster zur Herstellung traditioneller roter Kleider oder Hosenanzüge geben.", completion = "Hier sind die Muster, {name}. Ich bin mir sicher, dass Ihr die Ergebnisse dieses Herstellungsgeheimnisses wunderschön finden werdet." }
quests[80180] = { id = 80180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Verrat", description = "Ich habe Thermaplugg vertraut, {race}. Ich hätte nie vermutet, dass er mich und das ganze Gnomenvolk verraten würde. Und wofür? Macht? Reichtum? Alles Dinge, die er mit der Zeit auch so erlangt hätte. Jetzt sind wir aus unserer Heimat verdrängt worden und dieser Wahnsinnige ist dafür verantwortlich. Der König des Nichts...\n\nWir werden Gnomeregan zurückerobern, {name}. Wir werden nicht ruhen, bis die Stadt wieder unter unserer Kontrolle steht. Wenn Ihr Euch unserem Kampf anschließen wollt, habe ich eine einfache Bitte an Euch: Tötet den Verräter. Vernichtet Robogenieur Thermaplugg.", sourceObjective = "Reist nach Gnomeregan und tötet Robogenieur Thermaplugg. Kehrt zu Hochtüftler Mekkatorque zurück, wenn der Auftrag ausgeführt ist.", completion = "Ich stelle mir gern vor, dass das Letzte, was ihm durch den Kopf ging, bevor er zu Boden sank, Euer Fuß war, {race}. Jetzt, da Thermaplugg tot ist, sind wir der Verwirklichung unseres Plans, Gnomeregan wiederzuerobern, einen Schritt näher gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[80181] = { id = 80181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gyrobohrmatische Exkavation", description = "Es ist schrecklich, {name}. Wir werden nicht genug Teile haben, um unsere Flotte aus gyrobohrmatischen Exkavationatoren nach Dun Morogh zu bringen.\n\nWir brauchen Ersatzteile, {name}. Und welch besseren Ort als Gnomeregan könnte es geben, um Ersatzteile für unsere Fahrzeuge zu besorgen? Es heißt, dass Bots und Mechs dort herumlaufen wie Vieh auf der Weide.\n\nIhr müsst für mich nach Gnomeregan gehen und diese Roboter auseinandernehmen. Bringt mir ihre Gedärme. Zwei Dutzend sollten ausreichen.", sourceObjective = "Bringt 24 robomechanische Gedärme zu Shoni nach Stormwind.", progress = "Wenn dies ein Wettrennen wäre, hättet Ihr bereits verloren.", completion = "Das dürfte reichen, {name}. Ein gyrobohrmatischer Exkavationator ist geflickt; fehlen noch 398.", sourceObjectiveStatus = "unverified-source-field" }
quests[80182] = { id = 80182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das einzige Heilmittel ist mehr grünes Leuchten", description = "Eure Probe war nicht nur von unzureichender Menge, sondern auch noch verunreinigt.\n\nWas wir brauchen, ist mehr von dem grünen Leuchten. Die Troggs sind offensichtlich nicht stark genug verstrahlt, um unseren Ansprüchen zu genügen. Ihr werdet nach Gnomeregan gehen und etwas der radioaktiven Ablagerung direkt von der Quelle besorgen müssen. Ich spreche von den bestrahlten Schleimen, Lauerern und Schrecken. Seid gewarnt, diese Art von Ablagerung ist schwer abzufüllen. Es könnte Euch mehrere Versuche mit der Phiole kosten, bis Ihr eine geeignete Probe bergen könnt.", sourceObjective = "Reist nach Gnomeregan und bringt etwas von der hochwirksamen radioaktiven Ablagerung zurück. Seid gewarnt, die Ablagerung ist instabil und wird ziemlich schnell zerfallen.\n\nOzzie wird außerdem Eure schwere bleierne Sammelphiole benötigen, nachdem die Aufgabe erledigt ist.", progress = "Hm, Ihr leuchtet nicht. Das ist ein gutes Zeichen.", completion = "<Ozzie mustert Euch.> Erstaunlich, Ihr habt noch all Eure Gliedmaßen. Jetzt ist es an der Zeit nachzusehen, was dieses Zeug ausrichten kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[80241] = { id = 80241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herkunft der Schmiedekunst", description = "Als ich etwa so alt war wie Ihr, nahm mich ein Zwerg namens Galvan unter seine Fittiche und bildete mich in der Kunst des Rüstungsschmiedens aus. Bevor er sich nach Booty Bay aufmachte, nahm er mir das Versprechen ab, dass ich all denjenigen ein Lehrer sein würde, die den Wunsch hätten und entschlossen genug wären, selbst eine Schmiedelaufbahn einschlagen zu wollen. Und hier bin ich nun - all die Jahre später.\n\nAlso, es ist jetzt Zeit für Euch, ein bisschen was zu lernen. Stellt mir sechs goldene Schuppenarmschienen her, dann zeige ich Euch, was echte Schmiedekunst ist, {name}.", sourceObjective = "Bringt 6 goldene Schuppenarmschienen zu Hank dem Hammer in Stormwind.", progress = "Sollet Ihr vielleicht der nächste Zögling von Galvan sein?", completion = "Sehr gut, {name}! Hört zu und lernt.\n\nDie wahre Schmiedekunst entsteht niemals hier! \n\nDie wahre Schmiedekunst entsteht niemals hier! \n\nDie wahre Schmiedekunst entsteht nur hier und nirgends sonst! \n\nJetzt wisst Ihr, wo die wahre Schmiedekunst herkommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[80307] = { id = 80307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine komplette Lieferung", progress = "Habt Ihr etwas für mich?", completion = "Es ist alles da! Vielen Dank, {name}. Diese Vorräte sind an vorderster Front unentbehrlich." }
quests[80308] = { id = 80308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine komplette Lieferung", progress = "Habt Ihr etwas für mich?", completion = "Es ist alles da! Vielen Dank, {name}. Diese Vorräte sind an vorderster Front unentbehrlich." }
quests[80309] = { id = 80309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine komplette Lieferung", progress = "Habt Ihr etwas für mich?", completion = "Es ist alles da! Vielen Dank, {name}. Diese Vorräte sind an vorderster Front unentbehrlich." }
quests[80324] = { id = 80324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der irre König", description = "Ihr findet ein schmutziges, zerfleddertes Notizbuch, das mit Bauplänen und Notizen vollgekritzelt ist. Nach einem kurzen, oberflächlichen Blick wird Euch bereits klar, dass jede dieser Kreationen verheerendes Unheil anrichten könnte, sollte jemand so närrisch sein, sie tatsächlich zu bauen.", sourceObjective = "Bringt Thermapluggs Ingenieursnotizen zu Hochtüftler Mekkatorque in der Tüftlerstadt von Ironforge.", progress = "{name}, was habt Ihr da?", completion = "Ich kann Euch nicht genug dafür danken, diese Baupläne zurückgebracht zu haben. Ich möchte nicht mal daran denken, was mit Ironforge passiert wäre, wenn Thermaplugg diese Kreationen gegen uns gerichtet hätte.\n\nDas schreit nach einer Feier!", sourceObjectiveStatus = "unverified-source-field" }
quests[80325] = { id = 80325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der irre König", description = "Ihr findet ein schmutziges, zerfleddertes Notizbuch, das mit Bauplänen und Notizen vollgekritzelt ist. Nach einem kurzen, oberflächlichen Blick wird Euch bereits klar, dass jede dieser Kreationen verheerendes Unheil anrichten könnte, sollte jemand so närrisch sein, sie tatsächlich zu bauen.", sourceObjective = "Bringt Thermapluggs Ingenieursnotizen zu Nogg im Tal der Ehre in Orgrimmar.", progress = "Was habt Ihr für mich?", completion = "<Noggs Augen leuchten auf, während er durch die Sammlung aus Notizen und Bauplänen blättert.>\n\nDamit werde ich so viel Zeug in die Luft jagen.\n\nGute Arbeit, {name}. Ich glaube, das schreit nach einer Feier!", sourceObjectiveStatus = "unverified-source-field" }
quests[80411] = { id = 80411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Talisman von Kazdor", description = "Aus dem jüngsten Brief schließen wir, dass es sich bei dem letzten Artefakt, das Caius begehrt, um den Talisman von Kazdor handelt. Im Brief wird erwähnt, dass dieser Talisman sich irgendwo in Zul'Farrak befindet.\n\nIch möchte Euch bitten, Caius' Auftrag zu beenden, um nicht seinen Verdacht zu erregen. Das bedeutet, Ihr werdet alleine nach Zul'Farrak gehen müsst, wie immer.\n\nDoch bevor Ihr den Talisman übergebt, bringt ihn hierher. Wie werden Caius mehr überbringen, als er sich erhofft.", sourceObjective = "Findet den Talisman von Kazdor in Zul'Farrak. Bringt ihn anschließend zu Fahrad im Ravenholdt-Anwesen. Ihr müsst diese Aufgabe alleine erledigen.", progress = "Geht jetzt, wir haben keine Zeit zu verlieren.", completion = "Ihr habt flinke Finger, {name}. Also, auf zu Schritt zwei.", sourceObjectiveStatus = "unverified-source-field" }
quests[80417] = { id = 80417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiche buschige Schweife", progress = "Es ist unglaublich was Leute so alles schätzen! Wie wäre es zum Beispiel mit einem Stock, an dem man einen weichen buschigen Schwanz hängt. Ihr und ich mögen nun denken, dass derartiges keinerlei Wert hat... aber verpasst man so einem Quatsch einen netten Namen wie \"Wilder Wuschelschwanz\" und packt das Ganze in eine hübsche Schachtel, dann erscheint es den Leuten plötzlich wertvoll. Aus Tand werden heiß begehrte Objekte!\n\nBesorgt mir ein paar weiche buschige Schwänze von Wölfen aus Desolace und dem Ödland, dann werde ich Euch dafür Lose des Dunkelmond-Jahrmarkts geben.", completion = "Gut gemacht, {name}! Diese buschigen Schwänze werden unseren Besuchern gefallen - und das bedeutet sogleich glückliche Besucher... Besucher, die ihren Freunden vom Jahrmarkt erzählen und somit für noch mehr Publikum sorgen!\n\nHier sind Eure Lose! Viel Spaß auf dem Dunkelmond-Jahrmarkt... und vergesst nicht Euren Freunden von uns zu erzählen!" }
quests[80421] = { id = 80421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grüne Eisenarmschienen" }
quests[80422] = { id = 80422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grünes Feuerwerk" }
quests[80423] = { id = 80423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der größte Gnom der Welt!" }
quests[80453] = { id = 80453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beste ausgeheckte Pläne", description = "Bringt den Talisman zu Zan Shivsproket im Keller. Ich habe ihn gebeten, das Artefakt mit einem Mechanismus zu verbinden, der jeden Versuch nachweisen kann, Magie in es oder aus ihm heraus zu kanalisieren.\n\nDer Mechanismus ist mit bloßem Auge nicht zu sehen und explodiert, wenn er ausgelöst wird. Mit etwas Glück wird Caius bei der Explosion getötet. Aber zumindest werden seine Pläne mit dem Talisman durchkreuzt werden.", sourceObjective = "Bringt den Talisman von Kazdor zu Zan Shivsproket im Keller des Ravenholdt-Anwesens.", progress = "Ja, {class}? Braucht Ihr etwas von mir?", completion = "Ihr macht also bei Fahrads Auftrag mit? Nun gut. Gebt mir den Talisman und ich mache mich an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[80454] = { id = 80454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine letzte Lieferung", description = "Der Köder ist bereit, jetzt müssen wir die Falle auslegen. Ich habe den Talisman nach Fahrads Anweisungen angepasst. Alles, was Ihr nun tun müsst, ist, ihn auszuliefern, wie Ihr es mit den anderen Artefakten getan habt.\n\nGeht zur Hütte in der Nähe von Pyrewood und werft den Talisman in Caius' toten Briefkasten.\n\nWas danach passiert, liegt nicht in unseren Händen, vorerst.", sourceObjective = "Bringt den angepassten Talisman zu Caius totem Briefkasten in der Nähe von Pyrewood.", progress = "<Die Kiste ist leer.>", completion = "<Ihr legt den angepassten Talisman in die Kiste.>", sourceObjectiveStatus = "unverified-source-field" }
quests[80455] = { id = 80455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sich Zeit nehmen", description = "Der Auftrag ist erledigt. Kehrt besser nach Ravenholdt zurück und gebt Fahrad Bescheid.", sourceObjective = "Erstattet Fahrad am Ravenholdt-Anwesen Bericht.", completion = "Alles scheint nach Plan gelaufen zu sein. Gute Arbeit.\n\nJetzt können wir nur noch abwarten, bis Caius den nächsten Schritt macht. Ich werde Euch benachrichtigen, wenn es so weit ist. Euer Einsatz für das Anwesen ist noch nicht ganz abgeschlossen.\n\nDoch für den Moment könnt Ihr Euch zurücklehnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[80526] = { id = 80526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schande über mich", description = "Keinen Augenblick zu früh, {name}.\n\nDas Anwesen hat diesen \"C\" beobachtet, mit dem Ihr es zu tun habt.\n\nSeine wahre Identität ist Caius Schwarzholz, ein mächtiger Nutzer der Magie, der mit dem Syndikat zusammenarbeitet. Unsere Quellen sagen, dass er aus unbekanntem Grund Artefakte ansammelt. Wir haben erst vor Kurzem erfahren, dass *Ihr* ihn damit versorgt habt.\n\nCaius muss aufgehalten werden und ich glaube, Ihr solltet Euch darum kümmern. Zum Glück habe ich einen Plan. Sprecht mit mir, wenn Ihr bereit seid, Euren Namen reinzuwaschen.", sourceObjective = "Sprecht mit Fahrad, wenn Ihr bereit seid, seinen Plan anzuhören.", completion = "Gut, dann lasst uns zum Geschäft kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[81570] = { id = 81570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jarl braucht eine Klinge", description = "Ich habe zu schneiden. Ich kann Euch nicht sagen, was ich schneiden werde, aber... ich brauche eine Klinge. Eine ganz bestimmte Klinge...\n\nManche Leute nennen sie Mondstahlbreitschwert. Ich nenne sie eine Schwingklinge.\n\nHelft Ihr mir? Vielleicht findet Ihr sie in der Stadt. Wenn Ihr mit einem Schmied sprecht, macht er sie vielleicht besonders.\n\nAber schlaft nicht noch darüber. Was ich schneide, das hält nicht ewig...", sourceObjective = "Bringt ein Mondstahlbreitschwert zu Jarl in den Marschen von Dustwallow.", progress = "Habt Ihr meine Klinge???", completion = "Das ist eine gute Klinge. Sie schwingt gut. Es ist eine gute Schwingklinge. Danke. Danke, danke, danke!!! Jetzt möchte ich sie ausprobieren... \n\nSpäter. Ich probiere sie später aus. Aber wie ich schon sagte... danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[81682] = { id = 81682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der alte Champion", description = "Diese Arena mag unscheinbar wirken, aber ich sage Euch, sie war einst eine große Attraktion. Preiskämpfer, Abenteurer und sogar ein paar Kartellanhänger sind dort für Geld und Glorie in den Ring gestiegen.\n\nMit den Wetten und Lizenzen habe ich ein Vermögen verdient!\n\nDie Sache ging aber den Bach runter, als der alte Champion Kajind sich aufs Altenteil zurückzog. Er war eher in sich gekehrt und verließ Azshara eines Tages, ohne einen Ton zu sagen. Wenn Ihr ihn findet, könnten wir den Arenabetrieb wiederaufnehmen.", sourceObjective = "Sucht nach Kajind in Azshara.", completion = "<Ein Anflug von Wehmut legt sich kurz auf Kajinds Gesicht>\n\nIch bin in der Tat der sogenannte \"Champion\", den Ihr sucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[81697] = { id = 81697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entzahnt", description = "Ich kenne nur den Kampf, {name}. Während des Dritten Krieges sind zahllose Gegner durch meine Klinge gefallen. Als er vorbei war, schlug ich mich als Preiskämpfer durch. So bin ich auf die Arena von Gadgetzan gestoßen.\n\nIch habe dort ruhmreiche Tage erlebt, wurde des Lebens eines Champions jedoch bald müde. Nach Azshara kam ich auf der Suche nach einer größeren Herausforderung, einem Blaudrachen, der die Gegend südöstlich von hier durchstreift. Leider besiegte mich die Kreatur. Ich kam mit dem Leben davon, doch meine Klinge nahm sie in ihren Hort mit.\n\nWenn Ihr mein Schwert wiederbeschafft, kehre ich mit Euch nach Gadgetzan zurück.", sourceObjective = "Beschafft Kajinds Klinge von dem blauen Drachen in der Gegend südöstlich des Einsamen Grats in Azshara.", progress = "Ich mache Euch Euer Zögern nicht zum Vorwurf, {race}. Der Drache ist ein furchterregender Gegner.", completion = "Wo ich einst versagte, habt Ihr Erfolg gehabt. Ihr verdient meine tiefste Hochachtung und Dankbarkeit, {name}. Vielleicht besiegt Ihr mich auch in der Arena.", sourceObjectiveStatus = "unverified-source-field" }
quests[81716] = { id = 81716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldbericht zum Einfall beschaffen: Dämmerwald", description = "Elune sei Dank, dass Ihr hier seid, {name}. Wir werden von Dämonen überrannt, die durch das Tor des Smaragdgrünen Traums kommen. Ich habe den Kontakt zu meiner Späherin dort verloren. Sie heißt Charla. Bitte sucht sie am Traumtor und kehrt mit ihrem Feldbericht zurück. Und tötet auf Eurem Weg ein paar dieser schwärmenden Dämonen. Sobald Ihr mir den Bericht überreicht habt, erteile ich Euch einen Folgeauftrag, je nach den daraus gewonnenen Erkenntnissen.", sourceObjective = "Tötet Dämonen und bringt den Feldbericht zu Feldhauptmann Palandar.", progress = "Ihr habt den Bericht?", completion = "Danke, {name}! Auf der Grundlage der von Euch beschafften Informationen habe ich diesen Folgeauftrag für Euch. Danke für Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[81727] = { id = 81727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldbericht zum Einfall beschaffen: Ashenvale", description = "Elune sei Dank, dass Ihr hier seid, {name}. Wir werden von Dämonen überrannt, die durch das Tor des Smaragdgrünen Traums kommen. Ich habe den Kontakt zu meinem Späher dort verloren. Er heißt Gemeron. Bitte sucht ihn am Traumtor und kehrt mit seinem Feldbericht zurück. Und tötet auf Eurem Weg ein paar dieser schwärmenden Dämonen. Sobald Ihr mir den Bericht überreicht habt, erteile ich Euch einen Folgeauftrag, je nach den daraus gewonnenen Erkenntnissen.", sourceObjective = "Tötet Dämonen und bringt den Feldbericht zu Feldhauptmann Hannalah.", progress = "Ihr habt den Bericht?", completion = "Danke, {name}! Auf der Grundlage der von Euch beschafften Informationen habe ich diesen Folgeauftrag für Euch. Danke für Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[81728] = { id = 81728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldbericht zum Einfall beschaffen: Hinterland", description = "Elune sei Dank, dass Ihr hier seid, {name}. Wir werden von Dämonen überrannt, die durch das Tor des Smaragdgrünen Traums kommen. Ich habe den Kontakt zu meiner Späherin dort verloren. Sie heißt Fallia. Bitte sucht sie am Traumtor und kehrt mit ihrem Feldbericht zurück. Und tötet auf Eurem Weg ein paar dieser schwärmenden Dämonen. Sobald Ihr mir den Bericht überreicht habt, erteile ich Euch einen Folgeauftrag, je nach den daraus gewonnenen Erkenntnissen.", sourceObjective = "Tötet Dämonen und bringt den Feldbericht zu Feldhauptmann Korlian.", progress = "Ihr habt den Bericht?", completion = "Danke, {name}! Auf der Grundlage der von Euch beschafften Informationen habe ich diesen Folgeauftrag für Euch. Danke für Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[81729] = { id = 81729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldbericht zum Einfall beschaffen: Feralas", description = "Elune sei Dank, dass Ihr hier seid, {name}. Wir werden von Dämonen überrannt, die durch das Tor des Smaragdgrünen Traums kommen. Ich habe den Kontakt zu meinem Späher dort verloren. Er heißt Thandros. Bitte sucht ihn am Traumtor und kehrt mit seinem Feldbericht zurück. Und tötet auf Eurem Weg ein paar dieser schwärmenden Dämonen. Sobald Ihr mir den Bericht überreicht habt, erteile ich Euch einen Folgeauftrag, je nach den daraus gewonnenen Erkenntnissen.", sourceObjective = "Tötet Dämonen und bringt den Feldbericht zu Feldhauptmann Arunnel.", progress = "Ihr habt den Bericht?", completion = "Danke, {name}! Auf der Grundlage der von Euch beschafften Informationen habe ich diesen Folgeauftrag für Euch. Danke für Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[81730] = { id = 81730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämmerwaldmission I: Worgen besiegen", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums im Zwielichtshain und reist zum Alptraumeinfall im Verlassenen Obstgarten. Besiegt dort Worgen und kehrt zu mir zurück.", sourceObjective = "Besiegt 10 Alptraumläufer und 10 Alptraumwirker im Dämmerwald-Alptraumeinfall im Verlassenen Obstgarten und kehrt zu Feldhauptmann Palandar zurück.", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", sourceObjectiveStatus = "unverified-source-field" }
quests[81731] = { id = 81731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämmerwaldmission II: Oger besiegen", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums im Zwielichtshain und reist zum Alptraumeinfall im Ogerhort Vul'Gol. Besiegt dort Oger und kehrt zu mir zurück.", sourceObjective = "Besiegt 3 verwirrte Oger und 3 wahnsinnige Feuerwirker im Dämmerwald-Alptraumeinfall beim Ogerhort Vul'Gol und kehrt zu Feldhauptmann Palandar zurück.", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", sourceObjectiveStatus = "unverified-source-field" }
