quests[81745] = { id = 81745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämmerwaldmission XVI: Kroll Bergschatten retten", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums im Zwielichtshain und reist zum Alptraumeinfall im Verlassenen Obstgarten. Findet dort den schlafenden Druiden Kroll Bergschatten und bringt ihn in Sicherheit. Kehrt dann zu mir zurück.", sourceObjective = "Rettet Kroll Bergschatten aus dem Dämmerwald-Alptraumeinfall im Gasthaus des Verlassenen Obstgartens und kehrt zu Feldhauptmann Palandar zurück.", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", sourceObjectiveStatus = "unverified-source-field" }
quests[81746] = { id = 81746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämmerwaldmission XVII: Alara Hainheiler retten", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums im Zwielichtshain und reist zum Alptraumeinfall bei Yorgens Bauernhof. Findet dort die schlafende Druidin der Klaue Alara Hainheiler und bringt sie in Sicherheit. Kehrt dann zu mir zurück.", sourceObjective = "Rettet Alara Hainheiler im Dämmerwald-Alptraumeinfall im Stall von Yorgens Bauernhof und kehrt zu Feldhauptmann Palandar zurück.", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", sourceObjectiveStatus = "unverified-source-field" }
quests[81747] = { id = 81747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämmerwaldmission XVII: Elenora Marschenläufer retten", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums im Zwielichtshain und reist zum Alptraumeinfall im Ogerhort Vul'Gol. Findet dort die schlafende Druidin der Klaue Elenora Marschenläufer und bringt sie in Sicherheit. Kehrt dann zu mir zurück.", sourceObjective = "Rettet Elenora Marschenläufer aus dem Dämmerwald-Alptraumeinfall in den Ruinen eines Bauernhauses nahe des Ogerhorts Vul'Gol und kehrt zu Feldhauptmann Palandar zurück.", progress = "Ihr habt Elenora gerettet?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", sourceObjectiveStatus = "unverified-source-field" }
quests[81762] = { id = 81762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gute Nachrichten", description = "Seid gegrüßt, {name}. Ich habe gute Nachrichten: Ich habe meinen Freund kontaktiert und werde bald aufbrechen, um mich mit ihm zu treffen. Außerdem ist in Kalimdor eine weitere Kugel aufgetaucht. Ich kann nicht an zwei Orten gleichzeitig sein, deswegen würde ich Euch bitten, dass Ihr Euch statt meiner um diese neue Kugel kümmert, wenn Ihr wollt. Sprecht mit Katharina, sie hat weitere Anweisungen für Euch.", sourceObjective = "Sprecht mit Katharina der Reinen in der Kathedrale des Lichts in Stormwind.", completion = "Schön, Euch wiederzusehen, {name}. Bringen wir Euch auf den neuesten Stand.", sourceObjectiveStatus = "unverified-source-field" }
quests[81764] = { id = 81764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der rätselhafte Händler", description = "Ich grüße Euch erneut, {name}. Shaw und seine Spione haben uns berichtet, dass ein rätselhafter Händler gerade in Kalimdor eingetroffen ist, der eine Sammlung gefährlicher Artefakte loswerden möchte. Wir glauben jetzt, dass sich darunter eine Echokugel befindet. Der Mann hat sich im Gasthaus von Theramore in den Marschen von Dustwallow einquartiert. Begebt Euch schnell dorthin, beschafft die Kugel und sprecht mit niemandem darüber. Wir schicken Euch alleine los, damit unsere Gegner nicht auf Euch aufmerksam werden.\n\nSeid vorsichtig und geht mit dem Licht.", sourceObjective = "Reist nach Theramore und findet den rätselhaften Händler.", completion = "Ah, Ihr habt es geschafft! Katharina hat mich losgeschickt, damit ich Euch unterstütze. Doch wir müssen uns beeilen, unsere Beute ist entkommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[81765] = { id = 81765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elrick, Paladin der Silbernen Hand", description = "Der vor Euch stehende Paladin ist Euch unbekannt. Sprecht mit ihm und findet heraus, was er über den Händler und die momentane Lage weiß.", sourceObjective = "Sprecht mit Elrick, um mehr zu erfahren.", completion = "Dem Licht sei Dank für Euch, {class}! Ich hatte solche Angst. Ich dachte, diese Halunken bringen uns um!", sourceObjectiveStatus = "unverified-source-field" }
quests[81766] = { id = 81766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das blutige Schreiben", description = "Ihr findet ein Schreiben bei der Leiche des \"Paladins\". Es ist blutverschmiert und schwierig zu lesen, doch Ihr könnt eine Botschaft auf dem Pergament ausmachen. Lest sie Euch durch und kehrt für weitere Anweisungen zu Katharina zurück.", sourceObjective = "Bringt das Schreiben zu Katharina der Reinen in der Kathedrale des Lichts in Stormwind.", progress = "Es war also eine Falle... Das ist sehr besorgniserregend.", completion = "Welch ein Segen, dass Ihr unversehrt seid, {name}. Ich hoffe, dass Aeonas, wo auch immer er hingegangen sein mag, sich nicht in ähnliche Gefahr begeben hat. Er ist einfallsreich, daher muss ich glauben, dass es ihm gut geht. Wenn ich etwas von ihm höre, werde ich Euch umgehend benachrichtigen. Danke, {name}.\n\nOh, und noch etwas: Er hat mir aufgetragen, Euch dies zu geben, wenn Ihr zurückkehrt. Setzt es überlegt ein und geht mit dem Licht.", sourceObjectiveStatus = "unverified-source-field" }
quests[81768] = { id = 81768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashenvale-Mission I: Satyrn besiegen", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Bough Shadow und reist zum Alptraumeinfall in Satyrnaar. Besiegt dort Satyrn und kehrt zu mir zurück.", sourceObjective = "Besiegt 10 Traumfeuerverräter und 10 Traumfeuerhöllenrufer im Ashenvale-Alptraumeinfall in Satyrnaar und kehrt zu Feldhauptmann Hannalah zurück.", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", sourceObjectiveStatus = "unverified-source-field" }
quests[81769] = { id = 81769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashenvale-Mission II: Treants besiegen", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Bough Shadow und reist zum Alptraumeinfall am Holzfällerlager der Warsong. Besiegt dort Treants und kehrt zu mir zurück.", sourceObjective = "Besiegt 7 rachsüchtige Urtume im Ashenvale-Alptraumeinfall im Holzfällerlager der Warsong und kehrt zu Feldhauptmann Hannalah zurück.", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", sourceObjectiveStatus = "unverified-source-field" }
