quests[81778] = { id = 81778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashenvale-Mission XI: Katzengoldstaub", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Bough Shadow und beschafft Katzengoldstaub aus den Alptraumeinfällen. Wir können seine Magie zur Schadensumkehr nutzen. Ihr werdet die Hilfe eines Minenarbeiters brauchen.", sourceObjective = "Sammelt 10 Stück Katzengoldstaub in den Ashenvale-Alptraumeinfällen und kehrt zu Feldhauptmann Hannalah zurück.", progress = "Ihr habt den Katzengoldstaub?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", sourceObjectiveStatus = "unverified-source-field" }
quests[81779] = { id = 81779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashenvale-Mission XII: Traumerfüllte Drachenschuppe", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Bough Shadow und beschafft traumerfüllte Drachenschuppen von Drachkin aus den Alptraumeinfällen. Wir können ihre Magie zur Schadensumkehr nutzen. Ihr werdet die Hilfe eines Kürschners brauchen.", sourceObjective = "Sammelt 10 traumerfüllte Drachenschuppen in den Ashenvale-Alptraumeinfällen und kehrt zu Feldhauptmann Hannalah zurück.", progress = "Ihr habt die traumerfüllten Drachenschuppen?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", sourceObjectiveStatus = "unverified-source-field" }
