quests[81781] = { id = 81781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashenvale-Mission XIV: Zalius besiegen", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Bough Shadow und reist zum Alptraumeinfall in Forest Song. Besiegt dort den Satyr Zalius und kehrt zu mir zurück.", sourceObjective = "Besiegt Zalius im Ashenvale-Alptraumeinfall an der Basis der Ziggurat in Satyrnaar und kehrt zu Feldhauptmann Hannalah zurück.", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", sourceObjectiveStatus = "unverified-source-field" }
