quests[81783] = { id = 81783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashenvale-Mission XVI: Alyssian Windrufer retten", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Bough Shadow und reist zum Alptraumeinfall im Holzfällerlager der Warsong. Findet dort die schlafende Druidin der Klaue Alyssian Windrufer und bringt sie in Sicherheit. Kehrt dann zu mir zurück.", sourceObjective = "Rettet Alyssian Windrufer im Ashenvale-Alptraumeinfall am Fuß des Wachturms im Holzfällerlager der Warsong und kehrt zu Feldhauptmann Hannalah zurück.", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", sourceObjectiveStatus = "unverified-source-field" }
quests[81784] = { id = 81784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashenvale-Mission XVII: Doran Traumzweig retten", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Bough Shadow und reist zum Alptraumeinfall in Forest Song. Findet dort den schlafenden Druiden Doran Traumzweig und bringt ihn in Sicherheit. Kehrt dann zu mir zurück.", sourceObjective = "Rettet Doran Traumzweig im Ashenvale-Alptraumeinfall aus dem mondbeschienenen Pavillon in Forest Song und kehrt zu Feldhauptmann Hannalah zurück.", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", sourceObjectiveStatus = "unverified-source-field" }
quests[81785] = { id = 81785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashenvale-Mission XVIII: Maseara Herbstmond retten", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal zum Smaragdgrünen Traum in Bough Shadow und reist zum Alptraumeinfall in Satyrnaar. Findet dort die schlafende Druidin der Klaue Maseara Herbstmond und bringt sie in Sicherheit. Kehrt dann zu mir zurück.", sourceObjective = "Rettet Maseara Herbstmond im Alptraumeinfall von Ashenvale an der südöstlichen Zeltgruppe in Satyrnaar und kehrt zu Feldhauptmann Hannalah zurück.", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", sourceObjectiveStatus = "unverified-source-field" }
quests[81786] = { id = 81786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinterlandmission I: Mondkin besiegen", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Seradane und reist zum Alptraumeinfall am Skulk Rock. Besiegt dort die Mondkin und kehrt zu mir zurück.", sourceObjective = "Besiegt 20 gefallene Mondkin im Hinterland-Alptraumeinfall am Skulk Rock und kehrt zu Feldhauptmann Korlian zurück.", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", sourceObjectiveStatus = "unverified-source-field" }
quests[81787] = { id = 81787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinterlandmission II: Riesenschildkröten besiegen", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Seradane und reist zum Alptraumeinfall in Shaol'watha. Besiegt dort Riesenschildkröten und kehrt zu mir zurück.", sourceObjective = "Besiegt 20 Traumwasserschraubkiefern im Hinterland-Alptraumeinfall in Shaol'watha und kehrt zu Feldhauptmann Korlian zurück.", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", sourceObjectiveStatus = "unverified-source-field" }
quests[81788] = { id = 81788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinterlandmission III: Drachkin besiegen", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Seradane und reist zum Alptraumeinfall in Agol'watha. Besiegt dort Drachkin und kehrt zu mir zurück.", sourceObjective = "Besiegt 10 Zorneswelpen und 3 Sternenjägerwyrmkin im Hinterland-Alptraumeinfall in Agol'watha und kehrt zu Feldhauptmann Korlian zurück.", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", sourceObjectiveStatus = "unverified-source-field" }
quests[81789] = { id = 81789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinterlandmission IV: Drachen ausspionieren", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Seradane und reist zum Alptraumeinfall in Agol'watha. Beschafft dort einen Geheimdienstbericht von Traumwächter Laninar und kehrt zu mir zurück.", sourceObjective = "Beschafft einen Bericht von Traumwächter Laninar im Hinterland-Alptraumeinfall am Bogen von Agol'watha und kehrt zu Feldhauptmann Korlian zurück.", progress = "Ihr habt den Bericht?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", sourceObjectiveStatus = "unverified-source-field" }
quests[81790] = { id = 81790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedeutende Materialien", description = "Jede der Echokugeln ist auf einen anderen Aspekt ihres Meisters abgestimmt, und die Methode, auf die Ihr in Ashenvale zur Zerstörung der Kugel von Althalaxx gesetzt habt, wird bei der in unserem Besitz nicht funktionieren. Ich kenne ein Ritual, mit dem wir die Kugel möglicherweise erst destabilisieren und dann zerstören können, doch dafür sind Komponenten von bestimmter magischer Bedeutung erforderlich. Wir haben zwar bereits einige davon, doch die restlichen müsst Ihr beschaffen. Nehmt dies, es wird Euch bei Eurer Suche helfen.", sourceObjective = "Findet die in Gregorys Notiz aufgeführten Materialien und bringt sie zu Gregory an der Quelle der Blutgiftfälle im Teufelswald.", progress = "Die Beschaffung dieser Gegenstände war bestimmt ganz schön abenteuerlich. Gut gemacht.", completion = "Da wir die Materialien jetzt haben, muss ich das Ritual vorbereiten. Meldet Euch erst einmal bei Aeonas. Er möchte mit Euch sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[81801] = { id = 81801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr in die Arena", description = "Als Orc stehe ich zu meinem Wort. Ihr habt mich gerächt, und ich werde mich bei Euch revanchieren. Geht nach Gadgetzan und sagt Fizbuz, dass sein Champion zurückkommt.\n\nIch hoffe, wir zwei sehen uns im Ring.", sourceObjective = "Kehrt zu Fizbuz Mithril in Gadgetzan in Tanaris zurück.", completion = "Fantastisch! Die werden alle durchdrehen, wenn sie erfahren, dass der alte Kajind wieder da ist.\n\nUnd Ihr habt tatsächlich einen Drachen für den Kerl getötet?! Dann könntet Ihr ja fast selbst in den Ring steigen.\n\nIch spüre es schon, {name}. Hier findet bald ein absoluter Jahrhundertkampf statt!", sourceObjectiveStatus = "unverified-source-field" }
quests[81817] = { id = 81817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinterlandmission V: Schildkröte ausspionieren", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Seradane und reist zum Alptraumeinfall in Shaol'watha. Beschafft dort einen Geheimdienstbericht von Traumwächterin Sanathel und kehrt zu mir zurück.", sourceObjective = "Beschafft einen Bericht von Traumwächterin Sanathel im Hinterland-Alptraumeinfall hinter der Trommel in Shaol'watha und kehrt zu Feldhauptmann Korlian zurück.", progress = "Ihr habt den Bericht?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", sourceObjectiveStatus = "unverified-source-field" }
quests[81820] = { id = 81820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinterlandmission VI: Mondkin ausspionieren", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Seradane und reist zum Alptraumeinfall am Skulk Rock. Beschafft dort einen Geheimdienstbericht von Traumwächterin Valori und kehrt zu mir zurück.", sourceObjective = "Beschafft einen Bericht von Traumwächterin Valori im Hinterland-Alptraumeinfall am unterirdischen See von Skulk Rock und kehrt zu Feldhauptmann Korlian zurück.", progress = "Ihr habt den Bericht?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", sourceObjectiveStatus = "unverified-source-field" }
quests[81826] = { id = 81826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinterlandmission VII: Sternenberührtes Drachenei beschaffen", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Seradane und reist zum Alptraumeinfall in Agol'watha. Beschafft ein sternenberührtes Drachenei und bringt es mir.", sourceObjective = "Beschafft ein sternenberührtes Drachenei im Hinterland-Alptraumeinfall aus der zentralen Hütte von Agol'watha und kehrt zu Feldhauptmann Korlian zurück.", progress = "Ihr habt das Ei?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", sourceObjectiveStatus = "unverified-source-field" }
quests[81830] = { id = 81830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinterlandmission VIII: Elunarisches Relikt beschaffen", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Seradane und reist zum Alptraumeinfall am Skulk Rock. Beschafft ein elunarisches Relikt, das die Mondkin dort versteckt haben, und bringt es mir.", sourceObjective = "Beschafft ein elunarisches Relikt im Hinterland-Alptraumeinfall von dem hohen Vorsprung in Skulk Rock und kehrt zu Feldhauptmann Korlian zurück.", progress = "Ihr habt das Relikt?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", sourceObjectiveStatus = "unverified-source-field" }
quests[81832] = { id = 81832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinterlandmission IX: Traumperle beschaffen", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Seradane und reist zum Alptraumeinfall in Shaol'watha. Beschafft eine Traumperle, die die Schildkröten dort versteckt haben, und bringt sie mir.", sourceObjective = "Beschafft eine Traumperle im Hinterland-Alptraumeinfall aus einem Schlangenbrunnen in Shaol'watha und kehrt zu Feldhauptmann Korlian zurück.", progress = "Ihr habt die Perle?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", sourceObjectiveStatus = "unverified-source-field" }
