quests[81838] = { id = 81838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinterlandmission XIV: Verdammniskin besiegen", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Seradane und reist zum Alptraumeinfall am Skulk Rock. Besiegt dort den riesigen Mondkin, der als der Verdammniskin bekannt ist, und kehrt zu mir zurück.", sourceObjective = "Besiegt den Verdammniskin im Hinterland-Alptraumeinfall auf dem breiten Vorsprung von Skulk Rock und kehrt zu Feldhauptmann Korlian zurück.", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", sourceObjectiveStatus = "unverified-source-field" }
