quests[81872] = { id = 81872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feralasmission XVI: Mellias Erdpfleger retten", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Traum-Geäst und reist zum Alptraumeinfall in Oneiros. Findet dort den schlafenden Druiden der Klaue Mellias Erdpfleger und bringt ihn in Sicherheit. Kehrt dann zu mir zurück.", sourceObjective = "Rettet Mellias Erdpfleger im Feralas-Alptraumeinfall an der Treppe beim Jademirsee in Oneiros und kehrt zu Feldhauptmann Arunnel zurück.", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", sourceObjectiveStatus = "unverified-source-field" }
quests[81873] = { id = 81873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feralasmission XVII: Nerene Bachsänger retten", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Traum-Geäst und reist zum Alptraumeinfall bei den Zwillingskolossen. Findet dort die schlafende Druidin der Klaue Nerene Bachsänger und bringt sie in Sicherheit. Kehrt dann zu mir zurück.", sourceObjective = "Rettet Nerene Bachsänger im Feralas-Alptraumeinfall vom Lagerfeuer bei den Zwillingskolossen und kehrt zu Feldhauptmann Arunnel zurück.", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", sourceObjectiveStatus = "unverified-source-field" }
quests[81874] = { id = 81874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feralasmission XVIII: Jamniss Baumheiler retten", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Traum-Geäst und reist zum Alptraumeinfall bei den Ruinen von Rabenwind. Findet dort die schlafende Druidin der Klaue Jamniss Baumheiler und bringt sie in Sicherheit. Kehrt dann zu mir zurück.", sourceObjective = "Rettet Jamniss Baumheiler im Feralas-Alptraumeinfall beim nördlichen Rand der Ruinen von Rabenwind und kehrt zu Feldhauptmann Arunnel zurück.", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", sourceObjectiveStatus = "unverified-source-field" }
quests[81877] = { id = 81877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfnacht", description = "Alles steht für die große Neueröffnung der Arena von Gadgetzan bereit!\n\nDie Regeln sind einfach: Ihr habt drei Kämpfe und am Schluss den Champion. Zwischen den Kämpfen dürft Ihr eine kurze Pause machen, aber zu keiner Zeit die Arena verlassen. Wenn Ihr das tut, gilt es als Kapitulation.\n\nWenn Ihr bereit seid, geht der Kampf los!", sourceObjective = "Erringt den Sieg in der Arena von Gadgetzan.", completion = "Ihr habt da wirklich eine gute Show abgeliefert. Ich konnte mich kaum halten, kann ich Euch sagen! Die Einnahmen waren auch nicht zu schäbig.\n\nAls Champion bekommt Ihr einen Anteil davon und noch einen kleinen Bonus, weil Ihr all das möglich gemacht habt. Dem Sieger die Beute, wie man sagt.", sourceObjectiveStatus = "unverified-source-field" }
quests[81885] = { id = 81885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ritual", description = "Ich wollte Euch für Eure Mühen danken, {name}. Ohne Euch wäre ich sicherlich tot und die Diener der Legion immer noch im Besitz dieses gefährlichen Artefakts. Ich weiß, es ist schwierig, einem Agenten des Lichkönigs zu trauen, aber ich hoffe, dass wir meinen Freund wieder zum Licht bekehren können, wenn all das hier vorbei ist. Es ist deutlich zu erkennen, dass der Mann, den ich kannte, in seinem Inneren immer noch existiert. Er braucht vielleicht nur einen Anstoß.\n\nKommt, Gregory braucht unsere Hilfe beim Abschluss des Rituals. Wir sprechen danach weiter.", sourceObjective = "Sprecht mit Gregory, um das Ritual zu beginnen.", progress = "<Aeonas starrt leer die Klippe hinab, sichtlich schockiert von den Ereignissen.>", completion = "Mir fehlen die Worte, {name}. Dass ich Gregory nun wiedergesehen habe, erfüllt mich mit einer gefährlichen Hoffnung. Seit dem Augenblick unserer erneuten Verbindung ist sein Wesen offenbart, und es gab viele Anzeichen darauf, wie er wirklich ist, doch ich wollte sie nicht sehen.\n\nNehmt bitte diese verfluchte Kugel und lasst mich in Ruhe. Ich muss über vieles nachdenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[81900] = { id = 81900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die brennende Bestie", description = "Das Relief vor Euch zeigt eine Bestie mit zwei Köpfen, die Feuer speiend aus dem Dunklen Portal tritt. Auf einer Tafel unter der Darstellung steht: \"Calefactus der Entfesselte\".\n\nEure Intuition sagt Euch, dass die Twilightkultisten planen könnten, die zerstörerische Macht dieser Kreatur für ihre eigenen Zwecke einzusetzen.\n\nIhr vermutet, dass der nächste Schritt Eurer Jagd Euch in die Verwüsteten Lande führt. Dort könnte es jemanden geben, der mehr über diese Höllenbestie weiß.", sourceObjective = "Findet einen Experten für die Tiere in den Verwüsteten Landen.", completion = "Erzählt mir mehr über diese Bestie, {race}. Wir könnten dasselbe Ziel verfolgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[81917] = { id = 81917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bindende Ketten", description = "Ich habe die Kreatur, die Ihr \"Calefactus\" nennt, während meinen Feldstudien oft gesehen. Sie scheint ein nahezu unverwundbarer Kernhund zu sein, der aus reinen Teufelsenergien besteht.\n\nWenn das, was Ihr sagt, aber wahr ist, und der Twilight-Hammer plant, sie zu versklaven, dann gibt es vielleicht einen Weg, die Bestie zu bezwingen.\n\nDie Schattenanbeter im Südosten sind dafür bekannt, dunkle Rituale zu vollziehen, wie auch die Versklavung von Teufelskreaturen. Vielleicht kennen die Mitglieder ihres Ordens den Schlüssel, wie Calefactus zu schwächen ist?", sourceObjective = "Bringt 5 höllische Kettenverbunde zu Blutmagierin Lynnore in den Verwüsteten Landen.", progress = "Habt Ihr einen Weg gefunden, Calefactus zu schwächen, {race}?", completion = "Interessant... Ja, damit kann ich arbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[81919] = { id = 81919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter Kontrolle", description = "Ich habe ein Werkzeug aus den Kettenverbunden hergestellt, die Ihr gefunden habt. Leute wie Ihr würden es wohl eine Art \"Lasso\" nennen.\n\nDie Energie in dieser Kette ist besonders dafür geeignet, Dämonen zu binden, aber da Calefactus möglicherweise von der anderen Seite des Dunklen Portals kommt, glaube ich, sie wird auch bei ihm funktionieren.\n\nWenn Ihr ihn bezwingt, bringt mir eine Probe seines teuflischen Lebensblutes. So ein besonderes Geschöpf muss näher studiert werden.\n\nDie aktuelle Position von Calefactus innerhalb dieser Ödnis ist nicht bekannt, aber ich bin sicher, Ihr werdet ihn aufspüren, {class}.", sourceObjective = "Bringt das teuflische Lebensblut von Calefactus dem Entfesselten zu Blutmagierin Lynnore in den Verwüsteten Landen.", progress = "Findet diesen Kernhund schnell, {name}, bevor der Twilight-Hammer Euch zuvorkommt.", completion = "So eine exquisite Probe! Wer weiß, welche Geheimnisse in der Essenz einer Bestie von hinter dem Portal liegen?\n\nAls Dank möchte ich Euch mein Lasso überlassen. Ich bezweifle sowieso, dass ich so etwas je brauchen werde.", sourceObjectiveStatus = "unverified-source-field" }
quests[81924] = { id = 81924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weisheit der Wächter", description = "Welch Wissen der Kaldorei Ihr auch sucht, {class}, Ihr werdet es in diesen Ruinen nicht finden. Nicht mehr.\n\nDoch auch wenn das Körperliche vernichtet wurde, ist das Geistige geblieben.\n\nSucht die Schutzgeister von Azshara, des Hinterlands und von Feralas auf. Ihr werdet sie an ihren Schreinen erkennen. Bewährt Euch vor ihnen und lauscht ihren Worten. Ihre Weisheit wird auf Euch übertragen werden, damit sie nicht wie die vielen anderen Dinge hier an die Zeit verloren geht.", sourceObjective = "Bewährt Euch vor den Schutzgeistern von Azshara, des Hinterlands und von Feralas und kehrt dann zu Tyrisius in Feralas zurück.", completion = "Ihr habt Euch als gelehriger Schüler erwiesen, {name}. Das Bewahren uralten Wissens ist oft mühselig, doch Ihr habt diese Aufgabe bewundernswert gelöst.\n\nEs gibt noch zahlreiche weitere Geheimnisse in dieser Welt, die es aufzudecken gilt. Ich hoffe, diese Werkzeuge werden Euch auf dieser Reise helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[81944] = { id = 81944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine neu entdeckte Bestimmung", sourceObjective = "Ich... kann das nicht erklären, {race}, aber ich glaube, ich habe etwas, das Ihr braucht. Ich kam in dieses Land, um Wissen zu finden, und meine Suche führte mich jenen Berg dort hinten hinauf bis zu einem riesigen Fels aus Licht, der aus dem Himmel gefallen war. Als ich neben ihm sinnierte, beschenkte mich An'she mit vielen Dingen, und eins davon war eine neue Bestimmung in meinem Leben. Ein weiteres war eine Vision, wie Ihr und ich an diesem Ort diese Unterhaltung führten. Ich glaube, ich habe Euch das hier gegeben.\n\nBitte nimmt dieses Totem. Nutzt es überlegt im Dienste an An'she... und am Licht.", sourceObjectiveStatus = "unverified-source-field" }
quests[81947] = { id = 81947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutige Zauberei", progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, {name}. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte." }
