quests[81956] = { id = 81956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschwörerkodex", progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, {name}. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte." }
quests[81960] = { id = 81960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klären der Luft", description = "Die unleserlichen Notizen sind um eine Art Sapta geschlagen. Es ist düsterer, als Ihr es in Erinnerung habt, scheint aber von derselben Magie erfüllt zu sein. Ihr fühlt Euch unwohl, während Ihr es betrachtet, als wäre es von irgendeinem Übel besudelt worden. In der Nähe muss es einen Geisterfelsen geben, obwohl Euch kein heiliger Ort in dieser Gegend bekannt ist. Vielleicht könnt Ihr Euch diese seltsame Begebenheit erklären, wenn Ihr ihn findet.", sourceObjective = "Findet den besudelten Geisterfelsen und trinkt das düstere Luftsapta.", completion = "Ihr gebt Leben zurück. Ihr seid stark genug. Verstehe... ja... Ihr haltet die Verderbnis auf.\n\n\nSucht die Verderbnis und haltet sie auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[81967] = { id = 81967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überirdischer Schatz", sourceObjective = "Bitteschön, Boss!", sourceObjectiveStatus = "unverified-source-field" }
quests[81968] = { id = 81968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antwort auf den Ruf der Luft", description = "Ihr seid stark genug. Verstehe... ja. Ihr haltet die Verderbnis auf.\n\n<Der Elementar windet sich vor Unbehagen.>\n\nElemente in Feralas. Nutzt Essenz, um den Schrein zu finden.\n\nNehmt das Fragment. Es wird gegen die Verderbnis helfen.", sourceObjective = "Sammelt 3 Elementaressenzen von den Wasserelementaren an der Vergessenen Küste gegenüber der Insel Sardor in Feralas und kombiniert sie mit dem Luftfragment, um den verderbten Schrein dort aufzudecken.", progress = "Ihr habt den Schrein gefunden. Säubert ihn.", completion = "Verderbnis... muss jetzt gesäubert werden. Hilfe wird benötigt. Vielleicht... ja... Vielleicht helfen andere Elemente.", sourceObjectiveStatus = "unverified-source-field" }
quests[81974] = { id = 81974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Schrott für Ziri", description = "Ihr habt noch einen G-7-K.E.R.N.-Prozessor gefunden. Diese Einheit scheint in schlechterer Verfassung als die letzte zu sein. Aus ihr tropft eine sehr ätzend wirkende, tintenähnliche schwarze Flüssigkeit. Wahrscheinlich ist das Ding Schrott, doch Ziri könnte es vielleicht noch gebrauchen.", sourceObjective = "Sprecht mit Ziri \"Schraubenschlüssel\" Miniritzel in Gnomeregan.", progress = "Was habt Ihr da, {name}?", completion = "Oha! Ein G-7-K.E.R.N.-Prozessor. So einen habe ich noch nie gesehen, glaube ich. Am besten werft Ihr ihn einfach weg. Ich habe gehört, dass die Dinger sehr gefährlich sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[81975] = { id = 81975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein beunruhigender Austausch", description = "Moment, bitte, was?. Habt Ihr Euch den Kopf gestoßen? Warum sollte ich Euch bitten, mir eins dieser Teile zu bringen, um diesen Schrotteimer zu reparieren? Der Wiederverwertungsmat brauchte nur ein paar Sicherungseinsätze und Mithrilstreben und ein bisschen Verzauberungsessenz. Wenn ich eine voll funktionierende G-7-Einheit in das Ding einbauen würde... nicht auszudenken, was dann passieren könnte. Auf jeden Fall nichts Gutes. Explosionen, Feuer, interdimensionale Monster. Wahrscheinlich gäbe es eine echte Horrorvorstellung.", sourceObjective = "Sprecht mit Ziri.", completion = "Stellt Euch mal vor, ich würde einen G-7 in den Wiederverwertungsmat einbauen! Ich bin doch nicht lebensmüde!\n\n<Ziri kichert vor sich hin und wendet sich wieder ihrer Arbeit zu.>", sourceObjectiveStatus = "unverified-source-field" }
quests[81986] = { id = 81986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Alptraum schwächen", description = "Da Ihr Ziris Gerät jetzt habt, müsstet Ihr über alles verfügen, was Ihr braucht, um die Alptraumverschmelzung zu erledigen. Versammelt so viele Verbündete wie möglich und begebt Euch durch das Portal von Bough Shadow in Ashenvale wieder in den Alptraum. Findet und zerstört die Alptraumverschmelzung in ihren Versteck.\n\nAch, und noch etwas... Die Bestie besitzt einen besonderen Gegenstand, der für mich von größtem Interesse ist. Bringt mir alles, was Ihr bei ihrer Leiche findet, dann werde ich Euch großzügig entlohnen.", sourceObjective = "Vernichtet die Alptraumverschmelzung und bringt der schattenhaften Gestalt alles an Beute, was Ihr findet.", progress = "Wie läuft die Jagd?", completion = "Fantastische Arbeit, {name}. Jetzt zu Eurer Belohnung!\n\nWisst Ihr, ich wollte nur ein winziges Fragment eines Traums, der sich in diesem Mantel versteckt hatte, doch die Hülle an sich ist schon ein Schatz, und die gehört nun Euch. Ich glaube, Ihr werdet schon bald bemerken, dass sie gewisse einzigartige Eigenschaften hat, und wenn Ihr über die entsprechenden Fähigkeiten verfügt, sprecht mich noch einmal an. Dann kann ich Euch sicher sagen, wie Ihr die Hülle richtig nutzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[81987] = { id = 81987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblinische Lösungen", description = "Hey Ihr, kommt her und lasst Euch anschauen. Ja, das dachte ich mir, ich erkenne meilenweit, ob sich jemand den goblinischen Künsten verschrieben hat. Wir alle haben rußgeschwärzte Knöchel. Hört mal, ich brauche Eure Hilfe.\n\nIch wurde beauftragt, andere Goblins zu beraten, damit sie hier draußen die Nase vorn haben. Doch diese Gnome haben auch einen Experten herangezogen und überholen uns langsam. Ich möchte ein paar Ideen umsetzen, doch unterdessen bringt mir doch ein paar goblinische Landminen! Die könnt Ihr doch bauen, oder?", sourceObjective = "Bringt 5 goblinische Landminen zu Maximillian \"Dem Schmierer\" auf der Schimmernden Ebene.", progress = "Meine Mama hat immer gesagt: \"Wenn du einen fairen Kampf nicht gewinnen kannst, kämpfe keinen fairen Kampf.\" Deshalb werden wir dieses Problem so lösen, wie meine Vorfahren es getan haben. Wir spicken das Gelände mit hochempfindlichen Sprengkörpern!", completion = "Man stelle sich vor, die Dinger wurden von den Verteidigern am Hyjal zur Verteidigung gegen die Brennende Legion eingesetzt. Hier scheinen sie ähnlich gut zu passen.", sourceObjectiveStatus = "unverified-source-field" }
quests[82001] = { id = 82001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomenprobleme erwünscht", description = "Schlechte Nachrichten. Dieser gnomische Berater von denen ist mir einen Schritt voraus. Ihr Rennfahrer wird nicht mal den Boden berühren, habe ich gehört.\n\nDie versehen die Rennstrecke mit so Dingern namens \"Magneten\", über die man einfach nur gleitet, und das heißt: keine Explosion! Wenn der Kerl nicht auf die Mine tritt, müssen wir die Mine eben zu ihm bringen.\n\nIch glaube, wenn wir eine genügend starke elektrische Ladung haben, dürfte das unser Problem lösen. Geht nach Südwest-Un'Goro und beschafft mir das Horn eines Donnerstampferstegodons!", sourceObjective = "Bringt das Horn eines Donnerstampferstegodons zu Maximillian \"Dem Schmierer\".", progress = "Ich werde Euch nicht detailliert erklären, wie Magnete funktionieren, weil das ehrlich gesagt niemand weiß.", completion = "Ja, das dürfte reichen! Der perfekte natürliche Leiter, den wir brauchen! Späne davon werden als perfekter Zünder für die Minen fungieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[82002] = { id = 82002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist rot und riecht nach Lack?", description = "Diese neuen Landminen funktionieren perfekt, aber wir können die Sache nicht einfach nur sabotieren. Wir brauchen ein paar Verbesserungen für unsere eigenen Fahrzeuge, damit wir nicht als unehrlich gelten.\n\nDeswegen machen wir in dieser Hinsicht etwas ganz Offensichtliches: Wir lackieren die Dinger um! Und jetzt ratet mal, welche Farbe wir nehmen? Hotrod-Rot natürlich! Die schnellste Farbe der Welt!\n\nStellt sich die Frage: Wer hat den perfekten roten Lack? Diese Trottel vom Scharlachroten Kreuzzug natürlich! Schleicht Euch doch mal nach Hearthglen und holt mir was von diesem Rot.", sourceObjective = "Begebt Euch nach Hearthglen und findet eine Kiste mit scharlachrotem Farbstoff.", progress = "Es muss das Rot des Scharlachroten Kreuzzugs sein. Kein Blutrot, kein Feuerballrot, kein dämonisches Orcrot. Nein, das Rot des Scharlachroten Kreuzzugs und sonst nichts!", completion = "Dieser geschmackvolle Ton, der perfekte Farbverlauf. Und kein Hauch von Pink oder Orange! Einfach nur das beste Rot überhaupt. Oh ja, ich spüre jetzt schon, wie wir schneller werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[82003] = { id = 82003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegesrunde für die Goblins!", description = "Ha! Ich hab's geschafft! Äh... natürlich wir zusammen!\n\nDieser Amateurberater der Gnome da drüben wirft das Handtuch! Er zahlt uns aus, damit wir die Stadt verlassen! Übernehmt Ihr die Sache doch, ja? Das habt Ihr Euch verdient.", sourceObjective = "Sprecht mit Fizzbizz Kupferspule über eine Auszahlung.", completion = "Ich habe einen Vorschlag, der für uns beide von Interesse sein dürfte.", sourceObjectiveStatus = "unverified-source-field" }
quests[82004] = { id = 82004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schweigegeld", description = "Ich kann mir den Gesichtsverlust oder den finanziellen Verlust nicht leisten, den Ihr und Euer Goblinfreund mir verursacht. Folgender Vorschlag: Ich verrate Euch, wie gnomische Ingenieure bei ihrer Arbeit vorgehen. Als Gegenleistung macht Ihr Euch rar! Ich will Euch hier nicht mehr sehen!", sourceObjective = "Nehmt die Bestechung von Fizzbizz Kupferspule an.", completion = "Mehr kriegt Ihr erst einmal nicht! Kommt in einer Woche wieder, dann habe ich noch mehr für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[82008] = { id = 82008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomische Lösungen", description = "Seid gegrüßt, <geschätzter Kollege/geschätzte Kollegin>! Ich sehe schon, dass Ihr intellektuell auf höchstem Niveau seid! Doch nun zur Sache: Entlang der ganzen Rennstrecke scheinen Explosionen aufzutreten! Ein wenig verdächtig, findet Ihr nicht? Die Sicherheit unserer Fahrer steht an oberster Stelle. Bringt mir ein paar Gnomenunglücksverhinderungsgürtel! Hoffentlich löst das unser Problem auf kurze Sicht.", sourceObjective = "Bringt Fizzbizz Kupferspule 2 Gnomenunglücksverhinderungsgürtel.", progress = "Habt Ihr die Gürtel? Hier startet gleich ein Rennen, und wir brauchen die Teile SOFORT!", completion = "Sehr gut! Hoffentlich kommt unser Fahrer in einem Stück über die Ziellinie. Jetzt kümmern wir uns um ein größeres Problem.", sourceObjectiveStatus = "unverified-source-field" }
quests[82009] = { id = 82009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblinprobleme erwünscht", description = "Hört Ihr die Explosionen auf der Rennstrecke? Jetzt mal im Ernst? Weil ich nämlich fast taub bin. Egal...\n\nMagnete! Wenn wir Magnete vorsichtig entlang der Strecke platzieren und welche mit der umgekehrten Polarität unten an unseren Fahrzeugen anbringen, schweben wir einfach über die Minen! Nehmt das, ihr Goblins!\n\nUnd für das letzte Teil des Rätsels brauchen wir etwas, das eine elektrische Ladung halten kann, um die komplizierte elektrische Schalttafel zu versorgen.\n\nBegebt Euch nach Südwest-Un'goro und bringt mir von dort das Horn eines Donnerstampferstegodons!", sourceObjective = "Bringt Fizzbizz Kupferspule ein Horn eines Donnerstampferstegodons.", progress = "Das Horn eines Donnerstampferstegodons ist die perfekte organische Verbindung zur Versorgung der elektrischen Felder, die diese Magnete funktionieren lassen. Das hoffe ich zumindest, denn ich weiß nicht genau, was dahinter steckt.", completion = "Das wird reichen! Das Ding knistert noch vor Energie! Wenn ich noch Haare hätte, würden die mir alle zu Berge stehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[82010] = { id = 82010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwässern der Konkurrenz", description = "Die Zeit der reinen Verteidigung ist vorbei! Wir können nur gewinnen, wenn wir die Konkurrenz sabotieren! Ihren Treibstoff! Feuerblüte und Rum? DAGEGEN VERLIERT DIE GNOMISCHE GENIALITÄT? GEGEN PARFÜRMIERTEN ALKOHOL?\n\nWir müssen den Treibstoff unseres Gegner irgendwie unbemerkt sabotieren. Es gibt eine Blume mit einem unglaublichen Rotton. Die Verbindungen ihrer Blütenblätter werden instabil, wenn man sie auch nur leicht erhitzt.\n\nDer Scharlachrote Kreuzzug nutzt diese Blume für seine Farben. Geht nach Hearthglen und holt mir die Dinger.", sourceObjective = "Begebt Euch nach Hearthglen und findet eine Kiste mit scharlachrotem Farbstoff.", progress = "Nur der Scharlachrote Kreuzzug weiß, wo diese Blume wächst! Die Verbindungen sind stabil genug, um sie in den Farben ausreichend zu konzentrieren.", completion = "Ihr habt sie gefunden! Ja, wenn wir die Farbe einfach in den Treibstofftank unserer Gegner werfen, wird das ein schönes Spektakel! Eine Explosion? Schlimmer! Die fahren dann nur mit 76 % Prozent ihrer Kapazität! Und merken es nicht mal!", sourceObjectiveStatus = "unverified-source-field" }
quests[82011] = { id = 82011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegesrunde für die Gnome!", description = "Wir haben es geschafft! Die Goblins werfen das Handtuch. Und der von den Goblins angeheuerte Berater will sogar mit Euch persönlich sprechen! Aber gebt bitte nicht allzu sehr an, sonst macht der Euch noch einen Kopf kürzer!", sourceObjective = "Sprecht mit Maximillian \"Dem Schmierer\".", completion = "Ich bin alt genug, um zu wissen, wann ich verloren habe. Oder zumindest, wann man sich geschlagen geben sollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[82013] = { id = 82013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schweigegeld", description = "Ich sag Euch jetzt mal, wie das ablaufen wird. Ich kann mir Eure Präsenz hier nicht mehr leisten, also werdet Ihr sofort verschwinden. Als Gegenleistung für Euer großzügig abgepasstes Abrauschen dürft Ihr einmal in der Woche wiederkommen.\n\nDann schaut Ihr mal bei mir vorbei. Ihr werdet etwas Kleines auf dem Boden liegen sehen, das Ihr gerne aufheben könnt. Und aus Dankbarkeit dafür, dass Ihr mir diesen Dienst erweist, kann ich gar nicht anders, als Euch irgendwie zu belohnen.", sourceObjective = "Nehmt die Bestechung von Maximillian \"Dem Schmierer\" an.", completion = "Wir sehen uns nächste Woche.", sourceObjectiveStatus = "unverified-source-field" }
quests[82016] = { id = 82016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wirksame Tränke aus Atal'ai", progress = "Ich hab 'n ziemlich gutes Angebot für Euch! Ihr bringt mir Mojo, dass es nur von den Atal'ai gibt, und ich mach Euch 'nen Vorschlag: Ihr erhaltet Macht jenseits Eurer wildesten Vorstellungen. Aber Achtung, Mann, diese Macht nur kann in den Sümpfen genutzt werd'n, wo sie gefund'n wird. Angeblich soll'n die Atal'ai verbotene Hexerei praktizieren, und ich kenn' mich da gut aus.\n\nKlingt das gut? Hab'n wir 'nen Handel?", completion = "Ey, Ihr werdet diesen Handel nicht bereu'n!" }
